INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (1,'北京大学','北京','北京','https://hynu.site/logo/1.png','公办 本科 综合类 双一流 985 211 教育部直属。北京大学创办于1898年，是戊戌变法的产物，也是中华民族救亡图存、兴学图强的结果，初名京师大学堂，是中国近现代第一所国立综合性大学，辛亥革命后，于1912年改为现名。在悠久的文明历程中，古代中国曾创立太学、国子学、国子监等国家最高学府，在中国和世界教育史上具有重要影响。北京大学“上承太学正统，下立大学祖庭”，既是中华文脉和教育传统的传承者，也','2026-07-27 22:06:49','2026-08-08 00:11:46');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (2,'清华大学','北京','北京','https://hynu.site/logo/2.png','公办 本科 综合类 双一流 985 211 教育部直属。清华大学的前身清华学堂始建于1911年，1912年更名为清华学校。1928年更名为国立清华大学。1937年抗日战争全面爆发后南迁长沙，与北京大学、南开大学组建国立长沙临时大学，1938年迁至昆明改名为国立西南联合大学。1946年迁回清华园，设有文、法、理、工、农等5个学院、26个系。1952年全国高等学校院系调整后，清华大学成为一所多科性工业大学，重点为国家培养工程技术人','2026-07-27 22:06:49','2026-08-08 00:11:46');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (3,'中国人民大学','北京','北京','https://hynu.site/logo/3.png','公办 本科 综合类 双一流 985 211 教育部直属。中国人民大学（RenminUniversityofChina）是中国共产党创办的第一所新型正规大学，直属于教育部，由教育部与北京市共建。现任党委书记为张东刚、校长为马怀德。历史沿革和领导关怀中国人民大学前身是1937年诞生于抗日战争烽火中的陕北公学，以及后来的华北联合大学和北方大学、华北大学。学校始终与党和国家同呼吸、共命运，始终得到党中央的亲切关怀和高度重视。陕北','2026-07-27 22:06:49','2026-08-08 00:11:47');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (4,'北京航空航天大学','北京','北京','https://hynu.site/logo/4.png','公办 本科 理工类 双一流 985 211 工业和信息化部直属。柏彦故地，巍巍学府。抗美援朝战争期间，国家“急需办一所航空大学”。1951年，国家决定将北洋大学、厦门大学、西北工学院航空系并入清华大学航空工程学系，成立清华大学航空工程学院；将云南大学航空工程系并入四川大学航空系；将西南工业专科学校航空专修科并入华北大学工学院航空工程系。1952年，根据全国高等学校院系调整的要求，设立北京航空学院，由北京工','2026-07-27 22:06:49','2026-08-08 00:11:47');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (5,'北京理工大学','北京','北京','https://hynu.site/logo/5.png','公办 本科 理工类 双一流 985 211 工业和信息化部直属。北京理工大学的前身是1940年诞生于延安的自然科学院，是中国共产党历史上第一个开展自然科学教学与研究的专门机构。毛泽东同志亲自题写校名，无产阶级革命家李富春，无产阶级革命家、教育家徐特立，无产阶级革命家、无线电专家、经济专家李强等先后担任学校主要领导。1949年，学校迁入北京；1952年，定名为北京工业学院，成为新中国第一所国防工业院校；1988年，更','2026-07-27 22:06:49','2026-08-08 00:11:48');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (6,'北京师范大学','北京','北京','https://hynu.site/logo/6.png','公办 本科 综合类 双一流 985 211 教育部直属。北京师范大学是教育部直属重点大学，是一所以教师教育、教育科学和文理基础学科为主要特色的著名学府。学校的前身是1902年创立的京师大学堂师范馆，1908年改称京师优级师范学堂，独立设校，1912年改名为北京高等师范学校。1923年学校更名为北京师范大学，成为中国历史上第一所师范大学。1931年、1952年北平女子师范大学、辅仁大学先后并入北京师范大学。百余年来，北','2026-07-27 22:06:49','2026-08-08 00:11:49');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (7,'中国农业大学','北京','北京','https://hynu.site/logo/7.png','公办 本科 农林类 双一流 985 211 教育部直属。中国农业大学作为教育部直属高校，是我国现代农业高等教育的起源地，其历史起自于1905年成立的京师大学堂农科大学。1949年9月，由北京大学农学院、清华大学农学院和华北大学农学院合并为北京农业大学。1952年10月，北京农业大学农业机械系与中央农业部机耕化农业专科学校、华北农业机械专科学校、平原省农学院合并成立北京机械化农业学院，1985年10月更名为北京农业','2026-07-27 22:06:49','2026-08-08 00:11:49');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (8,'中央民族大学','北京','北京','https://hynu.site/logo/8.png','公办 本科 民族类 双一流 985 211 国家民委。中央民族大学是党和国家为解决民族问题、培养各民族干部和高级专门人才、促进中华民族大团结而创建的一所特色鲜明的高等院校。学校前身是中国共产党1941年9月在延安创办的延安民族学院。新中国成立后，经中央人民政府批准于1951年6月在北京成立中央民族学院。1978年确立为国家重点大学，1993年更名为中央民族大学，1999年进入国家“211工程”重点建设高校行列，2002年成','2026-07-27 22:06:49','2026-08-08 00:11:50');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (9,'南开大学','天津','天津','https://hynu.site/logo/9.png','公办 本科 综合类 双一流 985 211 教育部直属。南开大学是教育部直属重点综合性大学，是敬爱的周恩来总理的母校。学校肇始于1904年，成立于1919年，由近代爱国教育家严修、张伯苓秉承教育救国理念创办。1937年校园遭侵华日军炸毁，学校南迁，与北京大学、清华大学组建国立长沙临时大学，1938年迁至昆明改名为国立西南联合大学。1946年回津复校并改为国立。新中国成立以来，学校发展始终得到党和国家的亲切关怀。毛','2026-07-27 22:06:49','2026-08-08 00:11:51');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (10,'天津大学','天津','天津','https://hynu.site/logo/10.png','公办 本科 综合类 双一流 985 211 教育部直属。天津大学（TianjinUniversity），简称天大，其前身为北洋大学，始建于1895年10月2日，是中国第一所现代大学，开中国近代高等教育之先河。“甲午战争”失败后，学校在“自强之道以作育人才为本，求才之道以设立学堂为先”的办学宗旨下，由清光绪皇帝御笔朱批，创建于天津，由盛宣怀任首任督办。学校初名北洋大学堂，内设头等学堂（大学本科）和二等学堂（大学预科），','2026-07-27 22:06:49','2026-08-08 00:11:51');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (11,'大连理工大学','辽宁','大连','https://hynu.site/logo/11.png','公办 本科 理工类 双一流 985 211 教育部直属。大连理工大学是中国共产党在新中国成立前夕，面向新中国工业体系建设亲手创办的第一所新型正规大学。大连理工大学是教育部直属全国重点大学，是国家“211工程”和“985工程”重点建设高校，也是世界一流大学A类建设高校。学校以培养精英人才、促进科技进步、传承优秀文化、引领社会风尚为宗旨，秉承“海纳百川、自强不息、厚德笃学、知行合一”的大工精神和“由','2026-07-27 22:06:49','2026-08-08 00:11:52');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (12,'东北大学','辽宁','沈阳','https://hynu.site/logo/12.png','公办 本科 理工类 双一流 985 211 教育部直属。学校始建于1923年4月，是一所具有爱国主义光荣传统的大学。1928年8月至1937年1月，著名爱国将领张学良将军兼任校长。1931年“九·一八”事变后被迫流亡办学，先后辗转于北平、西安、开封、四川三台等地，在“一二·九”运动中，东大师生发挥了先锋队和主力军的重要作用。1949年3月，在东北大学工学院和理学院（部分）的基础上成立沈阳工学院。1950年8月，定名为东北工学','2026-07-27 22:06:49','2026-08-08 00:11:52');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (13,'吉林大学','吉林','长春','https://hynu.site/logo/13.png','公办 本科 综合类 双一流 985 211 教育部直属。吉林大学是教育部直属的全国重点综合性大学，坐落在吉林省长春市。学校始建于1946年，1960年被列为国家重点大学，1984年成为首批建立研究生院的22所大学之一，是国家“211工程”“985工程”和首批“双一流”大学建设高校。学校始终秉持“求实创新、励志图强”的校训，坚持以“学术立校、人才强校、创新兴校、开放活校、文化荣校”为发展战略，努力建设成为在国家和区','2026-07-27 22:06:49','2026-08-08 00:11:53');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (14,'哈尔滨工业大学','黑龙江','哈尔滨','https://hynu.site/logo/14.png','公办 本科 理工类 双一流 985 211 工业和信息化部直属。2020年6月7日，习近平总书记致信祝贺哈尔滨工业大学建校100周年。贺信指出，哈尔滨工业大学历史悠久。新中国成立以来，在党的领导下，学校扎根东北、爱国奉献、艰苦创业，打造了一大批国之重器，培养了一大批杰出人才，为党和人民作出了重要贡献。希望哈尔滨工业大学在新的起点上，坚持社会主义办学方向，紧扣立德树人根本任务，在教书育人、科研攻关等工作中，','2026-07-27 22:06:49','2026-08-08 00:11:53');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (15,'复旦大学','上海','上海','https://hynu.site/logo/15.png','公办 本科 综合类 双一流 985 211 教育部直属。复旦大学校名取自《尚书大传》之“日月光华，旦复旦兮”，始创于1905年，原名复旦公学，1917年定名为复旦大学，是中国人自主创办的第一所高等院校。上海医科大学前身是1927年创办的国立第四中山大学医学院。2000年，复旦大学与上海医科大学合并。目前，学校拥有哲学、经济学、法学、教育学、文学、历史学、理学、工学、医学、管理学、艺术学、交叉学科等12个学科门','2026-07-27 22:06:49','2026-08-08 00:11:54');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (16,'上海交通大学','上海','上海','https://hynu.site/logo/16.png','公办 本科 综合类 双一流 985 211 教育部直属。上海交通大学是我国历史最悠久、享誉海内外的高等学府之一，是教育部直属并与上海市共建的全国重点大学。经过120多年的不懈努力，上海交通大学已经建设成为一所“综合性、创新型、国际化”的国内一流、国际知名大学。十九世纪末，甲午战败，民族危难。中国近代著名实业家、教育家盛宣怀秉持“自强首在储才，储才必先兴学”的信念，于1896年在上海创办了交通大学','2026-07-27 22:06:49','2026-08-08 00:11:55');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (17,'同济大学','上海','上海','https://hynu.site/logo/17.png','公办 本科 综合类 双一流 985 211 教育部直属。同济的100年，是与中华民族命运休戚与共的100年；同济的100年，是与祖国科教事业心手相牵的100年；同济的100年，是与上海城市发展相濡以沫的100年。——摘自习近平同志在同济大学建校100周年庆祝大会上的讲话同心同德同舟楫，济人济事济天下！同济大学历史悠久、声誉卓著，是中国最早的国立大学之一，是教育部直属并与上海市共建的全国重点大学。经过118年的发展，同','2026-07-27 22:06:49','2026-08-08 00:11:55');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (18,'华东师范大学','上海','上海','https://hynu.site/logo/18.png','公办 本科 综合类 双一流 985 211 教育部直属。华东师范大学文脉绵长、声誉卓著，是教育部直属并与上海市重点共建的综合性研究型大学。学校成立于1951年10月16日，是以大夏大学（1924年）、光华大学（1925年）为基础，同时调进圣约翰大学、复旦大学、同济大学和浙江大学等高校的部分系科，在大夏大学原址上创办的。1959年被中共中央确定为全国16所重点院校之一。1972年与上海师范学院、上海体育学院等院校合并，改名','2026-07-27 22:06:49','2026-08-08 00:11:56');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (19,'南京大学','江苏','南京','https://hynu.site/logo/19.png','公办 本科 综合类 双一流 985 211 教育部直属。南京大学是一所历史悠久、声誉卓著的高等学府，其前身是创建于1902年的三江师范学堂，此后历经两江师范学堂、南京高等师范学校、国立东南大学、国立第四中山大学、国立中央大学、国立南京大学等历史时期，于1950年更名为南京大学。1952年，在全国高校院系调整中，南京大学调整出工学、农学、师范等部分院系后与创办于1888年的金陵大学文、理学院等合并，仍名南京大','2026-07-27 22:06:49','2026-08-08 00:11:56');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (20,'东南大学','江苏','南京','https://hynu.site/logo/20.png','公办 本科 综合类 双一流 985 211 教育部直属。东南大学坐落于六朝古都南京，是享誉海内外的著名高等学府。学校是国家教育部直属并与江苏省共建的全国重点大学，是国家“985工程”和“211工程”重点建设大学之一。2017年，东南大学入选世界一流大学建设A类高校名单。东南大学是一所历史悠久、底蕴深厚的大学。学校创建于1902年的三江师范学堂，后历经两江师范学堂、南京高等师范学校、国立东南大学、国立中央大','2026-07-27 22:06:49','2026-08-08 00:11:57');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (21,'浙江大学','浙江','杭州','https://hynu.site/logo/21.png','公办 本科 综合类 双一流 985 211 教育部直属。浙江大学是一所历史悠久、声誉卓著的高等学府，坐落于中国历史文化名城、风景旅游胜地杭州。浙江大学的前身求是书院创立于1897年，为中国人自己最早创办的新式高等学校之一。1928年，定名国立浙江大学。抗战期间，浙大举校西迁，在贵州遵义、湄潭等地办学七年，1946年秋回迁杭州。1952年全国高等学校院系调整时，浙江大学部分系科转入兄弟高校和中国科学院，留在杭','2026-07-27 22:06:49','2026-08-08 00:11:57');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (22,'中国科学技术大学','安徽','合肥','https://hynu.site/logo/22.png','公办 本科 理工类 双一流 985 211 中国科学院。中国科学技术大学是中国科学院所属的一所以前沿科学和高新技术为主，兼有医学、特色管理和人文学科的理工科大学。学校现有34个学院，含8个科教融合学院；设有苏州高等研究院、上海研究院、北京研究院、先进技术研究院、国际金融研究院、附属第一医院（安徽省立医院）。学校于1958年9月在北京创建，郭沫若任首任校长。这是我党为“两弹一星”事业而创办的红色大学','2026-07-27 22:06:49','2026-08-08 00:11:58');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (23,'厦门大学','福建','厦门','https://hynu.site/logo/23.png','公办 本科 综合类 双一流 985 211 教育部直属。厦门大学（XiamenUniversity），简称厦大（XMU），由著名爱国华侨领袖陈嘉庚先生于1921年创办，是中国近代教育史上第一所华侨创办的大学，也是一所与中国共产党同龄的大学。在建校100周年之际，中共中央总书记、国家主席、中央军委主席习近平向学校发来贺信。贺信指出，厦门大学是一所具有光荣传统的大学。100年来，学校秉持爱国华侨领袖陈嘉庚先生的立校志向，形成了“','2026-07-27 22:06:49','2026-08-08 00:11:58');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (24,'山东大学','山东','济南','https://hynu.site/logo/24.png','公办 本科 综合类 双一流 985 211 教育部直属。山东大学是一所历史悠久、学科齐全、实力雄厚、特色鲜明的教育部直属重点综合性大学，在国内外具有重要影响，1997年进入国家“211工程”建设序列，2001年被确定为国家“985工程”重点建设的高水平研究型大学，2017年迈入世界一流大学建设高校行列。山东大学前身是1901年创办的山东大学堂，被誉为中国近代高等教育起源性大学。其医学学科起源于1864年，开启近代中国高等','2026-07-27 22:06:49','2026-08-08 00:11:59');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (25,'中国海洋大学','山东','青岛','https://hynu.site/logo/25.png','公办 本科 综合类 双一流 985 211 教育部直属。中国海洋大学（OCEANUNIVERSITYOFCHINA），简称中国海大（OUC），是一所学科门类齐全、海洋和水产学科特色显著的教育部直属重点综合性大学，是国家“211工程”“985工程”和“双一流”重点建设高校。学校由教育部、自然资源部、山东省人民政府和青岛市人民政府共建。学校的发展目标是：到2030年，建成世界一流的综合性海洋大学；到本世纪中叶，建成特色显著的世界一流大学','2026-07-27 22:06:49','2026-08-08 00:12:00');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (26,'武汉大学','湖北','武汉','https://hynu.site/logo/26.png','公办 本科 综合类 双一流 985 211 教育部直属。江城多山，珞珈独秀；山上有黉，武汉大学。武汉大学是教育部直属重点综合性大学，是国家“985工程”和“211工程”重点建设高校，是首批“双一流”建设高校。武汉大学溯源于1893年清末湖广总督张之洞奏请清政府创办的自强学堂，历经传承演变，1928年定名为国立武汉大学，是近代中国第一批国立大学。1946年，学校已形成文、法、理、工、农、医6大学院并驾齐驱的办学格','2026-07-27 22:06:49','2026-08-08 00:12:00');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (27,'华中科技大学','湖北','武汉','https://hynu.site/logo/27.png','公办 本科 综合类 双一流 985 211 教育部直属。华中科技大学是国家教育部直属重点综合性大学，由原华中理工大学、同济医科大学、武汉城市建设学院于2000年5月26日合并成立，是国家“211工程”重点建设和“985工程”建设高校之一，是首批“双一流”建设高校。学校校园占地7000余亩，园内树木葱茏，碧草如茵，环境优雅，景色秀丽，绿化覆盖率72%，被誉为“森林式大学”。学校教学科研支撑体系完备，各项公共服务设施','2026-07-27 22:06:49','2026-08-08 00:12:01');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (28,'湖南大学','湖南','长沙','https://hynu.site/logo/28.png','公办 本科 综合类 双一流 985 211 教育部直属。湖南大学是教育部直属全国重点大学、“211工程”“985工程”和“世界一流大学”建设高校。学校办学起源于公元976年创办的岳麓书院，1903年岳麓书院与创办于1897年的时务学堂改制设立的湖南高等学堂合并，1926年定名湖南大学，1937年成为全国16所国立大学之一。新中国成立后，中国共产党主要创始人和早期领导人之一的李达担任第一任校长，毛泽东同志亲笔题写“湖南大学','2026-07-27 22:06:49','2026-08-08 00:12:01');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (29,'中南大学','湖南','长沙','https://hynu.site/logo/29.png','公办 本科 综合类 双一流 985 211 教育部直属。中南大学是教育部直属全国重点大学国家“211工程”首批重点建设高校国家“985工程”部省重点共建高水平大学和国家“2011计划”首批牵头高校2017年9月入选世界一流大学A类建设高校2022年2月入选第二轮“双一流”建设高校现任校党委书记安实、校长李建成中南大学坐落在中国历史文化名城——湖南省长沙市，占地面积317万平方米。跨湘江两岸，依巍巍岳麓，临滔滔湘水，环','2026-07-27 22:06:49','2026-08-08 00:12:02');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (30,'国防科技大学','湖南','长沙','https://hynu.site/logo/30.png','公办 本科 军事类 双一流 985 211。国防科技大学，前身是1953年创建于哈尔滨的中国人民解放军军事工程学院，即著名的“哈军工”，陈赓大将任首任院长兼政治委员。“哈军工”创办于抗美援朝期间，是新中国第一所高等军事工程学院，其卓越的办学成效铸就了我国国防科技和高等教育史上一座丰碑。1970年，学院主体南迁长沙，改名为长沙工学院。1978年，改建为中国人民解放军国防科学技术大学。1999年，长','2026-07-27 22:06:49','2026-08-08 00:14:36');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (31,'中山大学','广东','广州','https://hynu.site/logo/31.png','公办 本科 综合类 双一流 985 211 教育部直属。中山大学是伟大的民族英雄、伟大的爱国主义者、中国民主革命的伟大先驱孙中山先生于1924年亲手创办，中国共产党早期领导人共同创建的大学，是中国传播马克思主义的重要发源地之一，具有优良革命传统、爱国奋斗精神和卓越品格追求。中山大学起初校名为国立广东大学。孙中山先生逝世后，学校于1926年定名为国立中山大学。今日的中山大学，由1952年院系调整后分设的','2026-07-27 22:06:49','2026-08-08 00:12:03');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (32,'华南理工大学','广东','广州','https://hynu.site/logo/32.png','公办 本科 综合类 双一流 985 211 教育部直属。华南理工大学地处广州，是直属教育部的全国重点大学，校园分为五山校区、大学城校区和广州国际校区，是首届“全国文明校园”获得单位。学校办学源远流长，最早可溯源至1918年成立的广东省立第一甲种工业学校（世称“红色甲工”）；正式组建于1952年全国高等院校调整时期，是新中国“四大工学院”之一；1960年成为全国重点大学；1981年经国务院批准为首批博士和硕士','2026-07-27 22:06:49','2026-08-08 00:12:03');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (33,'四川大学','四川','成都','https://hynu.site/logo/33.png','公办 本科 综合类 双一流 985 211 教育部直属。岷峨挺秀，锦水含章。巍巍学府，德渥群芳。四川大学是教育部直属全国重点大学，是国家布局在中国西部重点建设的高水平研究型综合大学，地处美丽的“天府之国”，有望江、华西、江安和眉山四个校区，占地面积8050亩。四川大学由原四川大学、原成都科技大学、原华西医科大学三所全国重点大学经过两次合并而成。原四川大学起始于1896年四川总督鹿传霖奉光绪特旨创办','2026-07-27 22:06:49','2026-08-08 00:12:04');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (34,'电子科技大学','四川','成都','https://hynu.site/logo/34.png','公办 本科 理工类 双一流 985 211 教育部直属。电子科技大学坐落于素有“天府之国”美誉的四川省成都市，是教育部直属全国重点大学，国家首批“211工程”“985工程”重点建设大学，首批国家“双一流”建设高校，被誉为“中国民族电子工业摇篮”和“中国电子类院校排头兵”。学校始建于1956年，原名成都电讯工程学院，是在周恩来总理的亲自部署下，由交通大学（现上海交通大学、西安交通大学）、南京工学院（现','2026-07-27 22:06:49','2026-08-08 00:12:04');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (35,'重庆大学','重庆','重庆','https://hynu.site/logo/35.png','公办 本科 综合类 双一流 985 211 教育部直属。重庆大学是中央直管、教育部直属的全国重点大学。学校创办于1929年，提出建设“完备弘深之大学”的愿景，到20世纪40年代发展成为文理工商法医各学科齐全的综合性大学。经过1952年全国院系调整，成为以工科为主的多科性大学。1960年被确定为全国重点大学。改革开放后，学校进行了全面的恢复调整和改革建设，成为一所以工为主、多学科协调发展的高校，1998年获批国家“','2026-07-27 22:06:49','2026-08-08 00:12:05');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (36,'西安交通大学','陕西','西安','https://hynu.site/logo/36.png','公办 本科 综合类 双一流 985 211 教育部直属。西安交通大学是我国最早兴办、享誉海内外的著名高等学府，是教育部直属重点大学。西迁以来，一代代交大人扎根西部、服务国家，为西部发展和国家建设作出了卓越贡献，以实际行动铸就了第一批纳入中国共产党人精神谱系的西迁精神。2017年12月，习近平总书记对学校15位老教授来信作出重要指示。在2018年新年贺词中，习近平总书记再次提到“西安交大西迁的老教授”。20','2026-07-27 22:06:49','2026-08-08 00:12:05');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (37,'西北工业大学','陕西','西安','https://hynu.site/logo/37.png','公办 本科 理工类 双一流 985 211 工业和信息化部直属。西北工业大学（简称西工大或西北工大）坐落于陕西西安，是一所以航空、航天、航海等领域人才培养和科学研究为发展特色的国家“双一流”建设高校，隶属于工业和信息化部。学校脉源三支、强强融合（国立西北工学院、华东航空学院、哈尔滨军事工程学院空军工程系），1960年被中共中央确定为全国重点大学，“七五”“八五”均被国务院列为国家重点建设高校之一，1995','2026-07-27 22:06:49','2026-08-08 00:12:06');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (38,'西北农林科技大学','陕西','咸阳','https://hynu.site/logo/38.png','公办 本科 农林类 双一流 985 211 教育部直属。西北农林科技大学地处中华农耕文明发祥地、国家级农业高新技术产业示范区——陕西杨凌，是教育部直属、国家“985工程”和“211工程”重点建设高校，首批入选国家“世界一流大学和一流学科”建设高校，2022年入选国家第二轮“双一流”建设高校，2个学科入选“双一流”建设学科。学校前身是创建于1934年的国立西北农林专科学校，为西北地区最早的高等农林教育学府。','2026-07-27 22:06:49','2026-08-08 00:12:08');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (39,'兰州大学','甘肃','兰州','https://hynu.site/logo/39.png','公办 本科 综合类 双一流 985 211 教育部直属。兰州大学是教育部直属全国重点综合性大学，在国家高等教育格局中具有重要战略地位，在国内外具有重要影响和良好声誉。学校创建于1909年，始为甘肃法政学堂，是中国西北地区第一个具有现代意义的高等学校。1928年，扩建为兰州中山大学。1946年，更名为国立兰州大学。新中国成立后，在高等学校院系调整中，被确定为国家14所综合性大学之一。改革开放以来，先后入选“','2026-07-27 22:06:49','2026-08-08 00:12:08');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (40,'北京交通大学','北京','北京','https://hynu.site/logo/40.png','公办 本科 理工类 双一流 211 教育部直属。北京交通大学是教育部直属，教育部、交通运输部、北京市人民政府和中国国家铁路集团有限公司共建的全国重点大学，是国家“211工程”“985工程优势学科创新平台”“双一流”建设高校。北京交通大学作为交通大学的三个源头之一，历史渊源可追溯到1896年，前身是清政府创办的铁路管理传习所，是中国第一所专门培养管理人才的高等学校，是中国近代铁路管理、电信教育','2026-07-27 22:06:49','2026-08-08 00:12:09');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (41,'北京工业大学','北京','北京','https://hynu.site/logo/41.png','公办 本科 理工类 双一流 211 北京市。北京工业大学（BeijingUniversityOfTechnology）创建于1960年，是一所以工为主的多科性市属重点大学，覆盖工学、理学、经济学、管理学、文学、法学、教育学、艺术学、交叉学科等9个学科门类，1981年成为国家教育部批准的第一批硕士学位授予单位，1985年成为博士学位授予单位，1996年通过国家“211工程”预审，正式跨入国家二十一世纪重点建设的百所大学的行列。学校于2017年正式','2026-07-27 22:06:49','2026-08-08 00:12:10');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (42,'北京科技大学','北京','北京','https://hynu.site/logo/42.png','公办 本科 理工类 双一流 211 教育部直属。北京科技大学的历史渊源可追溯至1895年北洋西学学堂创办的中国近代史上第一个矿冶学科，1952年，学校由天津大学（原北洋大学）、清华大学等6所国内著名大学的矿冶系科组建而成，名为北京钢铁工业学院，是新中国建立的第一所钢铁工业高等学府。1960年，更名为北京钢铁学院，并被批准为全国重点高等学校。1984年，成为全国首批正式成立研究生院的高等学校之一。1988年','2026-07-27 22:06:49','2026-08-08 00:12:10');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (43,'北京化工大学','北京','北京','https://hynu.site/logo/43.png','公办 本科 理工类 双一流 211 教育部直属。北京化工大学创办于1958年，原名北京化工学院，是新中国为“培养尖端科学发展所需的高级化工技术人才”而创建的一所高水平大学。作为教育部直属的全国重点大学，国家“211工程”和“‘985’优势学科创新平台”重点建设院校，国家“双一流”建设高校，北京化工大学肩负着高层次创新人才培养和基础性、前瞻性科学研究以及原创性高新技术开发的使命。经过67年建设发','2026-07-27 22:06:49','2026-08-08 00:12:11');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (44,'北京邮电大学','北京','北京','https://hynu.site/logo/44.png','公办 本科 理工类 双一流 211 教育部直属。七十载风雨砥砺，七十载春华秋实。明光之北、蓟门之南，古老的城墙，见证了永不消逝的电波；鸿雁翱翔、银杏巍巍，坚实的土地，承载了信息黄埔的传奇。北京邮电大学是新中国第一所邮电高等学府，是教育部直属、工业和信息化部共建的全国重点大学，是一所以信息科技为特色、工学门类为主体、工管文理交叉融合的研究型大学，是我国信息科技人才的重要培养基地。','2026-07-27 22:06:49','2026-08-08 00:12:12');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (45,'北京林业大学','北京','北京','https://hynu.site/logo/45.png','公办 本科 农林类 双一流 211 教育部直属。北京林业大学是教育部直属，教育部、国家林业和草原局、北京市人民政府共建的全国重点大学，是国家首批“211工程”重点建设高校、“优势学科创新平台”建设项目试点高校和“双一流”建设高校，是教育部高等学校林学类专业教学指导委员会主任委员单位、教育部高等学校自然保护与环境生态类专业教学指导委员会主任委员单位、教育部高等学校林业工程类专业教学指','2026-07-27 22:06:49','2026-08-08 00:12:12');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (46,'北京中医药大学','北京','北京','https://hynu.site/logo/46.png','公办 本科 医药类 双一流 211 教育部直属。北京中医药大学是一所以中医药学为主干学科的教育部直属高校，始建于1956年，前身为北京中医学院，是国务院批准最早创办的高等中医药院校。1960年，被中央确定为全国重点高校；1993年，更名为北京中医药大学，2000年，与北京针灸骨伤学院合并。学校坚持落实立德树人根本任务，秉承“勤求博采、厚德济生”校训，将“人心向学、传承创新”理念贯穿育人工作始终，培养','2026-07-27 22:06:49','2026-08-08 00:12:13');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (47,'北京外国语大学','北京','北京','https://hynu.site/logo/47.png','公办 本科 语言类 双一流 211 教育部直属。北京外国语大学（简称“北外”）坐落在北京市海淀区西三环北路，是教育部直属、首批“211工程”高校、“985”优势学科创新平台高校、首批“双一流”建设高校。北外是中国共产党创办的第一所外国语高等学校，前身是1941年成立于延安的中国抗日军政大学三分校俄文队，后发展为中央军委外国语学校，建校始隶属于党中央领导。新中国成立后，学校归外交部领导，1954年更','2026-07-27 22:06:49','2026-08-08 00:12:14');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (48,'中国传媒大学','北京','北京','https://hynu.site/logo/48.png','公办 本科 综合类 双一流 211 教育部直属。中国传媒大学是教育部直属的首批“双一流”建设高校，“211工程”重点建设大学，“985优势学科创新平台”重点建设高校。学校始建于1954年，是在刘少奇、周恩来等老一辈党和国家领导人直接关怀下建立的，新中国成立后党创办的第一所传媒类高校，2004年8月由北京广播学院更名为中国传媒大学。办学69年来，学校秉承“立德、敬业、博学、竞先”的校训，传承“忠诚、自信','2026-07-27 22:06:49','2026-08-08 00:12:14');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (49,'中央财经大学','北京','北京','https://hynu.site/logo/49.png','公办 本科 财经类 双一流 211 教育部直属。中央财经大学是教育部、财政部和北京市人民政府共建的教育部直属高校，是国家“双一流”建设、“211工程”建设和首批“985优势学科创新平台”项目建设高校。学校始建于1949年11月6日，创办之初由财政部主管，历经华北税务学校、中央税务学校、中央财政学院、中央财经学院、中央财政金融学院等发展阶段，1996年更名为中央财经大学，2000年由财政部划转教育部直属管理','2026-07-27 22:06:49','2026-08-08 00:12:15');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (50,'对外经济贸易大学','北京','北京','https://hynu.site/logo/50.png','公办 本科 财经类 双一流 211 教育部直属。对外经济贸易大学（UniversityofInternationalBusinessandEconomics）是教育部直属高校，教育部与商务部共建高校，首批国家“双一流”建设和首批“211工程”建设高校。对外经济贸易大学办学历史悠久，是新中国第一所培养对外贸易专门人才的高等学府，创建于1951年，前身为隶属于中央人民政府贸易部的高级商业干部学校。1953年更名为北京对外贸易专科学校。1954年，中国人民大学对','2026-07-27 22:06:49','2026-08-08 00:12:15');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (51,'北京体育大学','北京','北京','https://hynu.site/logo/51.png','公办 本科 体育类 双一流 211 国家体育总局。北京体育大学诞生于新中国体育事业发轫之际，始终肩负着“内强民族体质，外争国家荣光”的使命。自1953年创办以来，始终与共和国发展共命运，以卓越办学实践铸就行业典范，在世界高等体育教育版图中标注中国坐标。学校隶属国家体育总局，作为全国首批重点院校、国家“211工程”重点建设大学，以及国家首批和新一轮“双一流”建设高校，以悠久的历史、深厚的底蕴','2026-07-27 22:06:49','2026-08-08 00:12:16');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (52,'中国政法大学','北京','北京','https://hynu.site/logo/52.png','公办 本科 政法类 双一流 211 教育部直属。中国政法大学是一所以法学学科为特色和优势，兼有政治学、经济学、管理学、文学、历史学、哲学、教育学、理学、工学等学科的“211工程”重点建设大学，“‘985工程’优势学科创新平台”“2011计划”和“111计划”（高校学科创新引智计划）重点建设高校，国家“双一流”建设高校，直属于国家教育部，由教育部与北京市共建，正致力于建设世界一流大学和一流学科。现','2026-07-27 22:06:49','2026-08-08 00:12:17');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (53,'华北电力大学','北京','北京','https://hynu.site/logo/53.png','公办 本科 理工类 双一流 211。华北电力大学是教育部直属全国重点大学、国家“211工程”和“985工程优势学科创新平台”重点建设大学。2017年，学校入选国家“双一流”建设高校行列，重点建设能源电力科学与工程学科群，全面开启建设世界一流学科和高水平研究型大学的新征程。2022年，学校顺利通过首轮“双一流”建设评估并进入第二轮建设高校名单，电气工程学科入选第二轮“双一流”建设学科。202','2026-07-27 22:06:49','2026-08-08 00:14:38');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (54,'中国矿业大学','江苏','徐州','https://hynu.site/logo/54.png','公办 本科 综合类 双一流 211 教育部直属。中国矿业大学是教育部直属的全国重点高校，先后进入国家“211工程”“985优势学科创新平台项目”和国家“双一流”建设高校行列。学校为全国首批具有博士和硕士授予权的高校之一，设有国家批准的研究生院。学校现坐落于素有“五省通衢”之称的国家历史文化名城——江苏省徐州市，有文昌和南湖两个校园。学校现有2个国家“双一流”建设学科、1个一级学科国家重点学','2026-07-27 22:06:49','2026-08-08 00:12:17');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (55,'中国石油大学','山东','青岛','https://hynu.site/logo/55.png','公办 本科 理工类 双一流 211。中国石油大学（华东）是教育部直属全国重点大学，是国家“211工程”重点建设和开展“985工程优势学科创新平台”建设并建有研究生院的高校之一。学校是教育部和五大能源企业集团公司、教育部和山东省人民政府共建的高校，是石油石化高层次人才培养的重要基地，被誉为“石油科技、管理人才的摇篮”，现已成为一所以工为主、石油石化特色鲜明、多学科协调发展的大','2026-07-27 22:06:49','2026-08-08 00:14:39');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (56,'中国地质大学','湖北','武汉','https://hynu.site/logo/56.png','公办 本科 理工类 双一流 211。中国地质大学（武汉）是教育部直属全国重点大学，是国家批准设立研究生院的大学，是国家首批“211工程”“985优势学科创新平台”和“双一流”建设高校。学校以地球科学为主要特色，学科涵盖理学、工学、文学、管理学、经济学、法学、教育学、艺术学等门类，地质学、地质资源与地质工程2个一级学科入选“双一流”建设学科。经过多年建设，学校形成“一校两区四基','2026-07-27 22:06:49','2026-08-08 00:14:41');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (57,'天津医科大学','天津','天津','https://hynu.site/logo/57.png','公办 本科 医药类 双一流 211 天津市。学校前身天津医学院创建于1951年，是新中国成立后建立的第一所高等医学院校，著名内分泌学家、医学教育家朱宪彝教授为首任校长。建校之初，汇聚了以赵以成、金显宅等为代表的一大批医学专家，秉持“为党育人、为国育才”的初心，致力于为国家培养急需的医学人才，逐步建设成为华北地区重要的医学及医学教育中心之一。1994年6月天津医学院与天津第二医学院正式组','2026-07-27 22:06:49','2026-08-08 00:12:18');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (58,'河北工业大学','天津','天津','https://hynu.site/logo/58.png','公办 本科 理工类 双一流 211 河北省直属。河北工业大学的前身是创办于1903年的北洋工艺学堂，是我国最早的培养工业人才的高等学校之一，创办了全国最早的高校校办工厂。1929年改称河北省立工业学院，1995年更名为河北工业大学。学校1996年跻身国家首批“211工程”重点建设高校行列；2014年由河北省、天津市和教育部共建；2017年，入选国家“双一流”建设高校；2022年，入选新一轮国家“双一流”建设高校。120余年','2026-07-27 22:06:49','2026-08-08 00:12:18');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (59,'太原理工大学','山西','太原','https://hynu.site/logo/59.png','公办 本科 理工类 双一流 211 山西省直属。太原理工大学是一所历史悠久、底蕴深厚、特色鲜明的世纪学府，坐落于具有2500多年建城史的国家历史文化名城——太原。其前身是创立于1902年的山西大学堂西学专斋，为中国创办最早的三所国立大学堂之一。1953年，学校独立建校，定名太原工学院，直属国家高教部；1984年更名为太原工业大学。1997年，太原工业大学与直属于国家煤炭工业部的山西矿业学院（始建于1958年）','2026-07-27 22:06:49','2026-08-08 00:12:19');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (60,'内蒙古大学','内蒙古','呼和浩特','https://hynu.site/logo/60.png','公办 本科 综合类 双一流 211 内蒙古自治区。内蒙古大学位于内蒙古自治区首府呼和浩特市，距北京480公里，是新中国成立后党和国家在边疆民族地区创办的第一所综合大学。学校创办于1957年，时任国务院副总理、自治区主席乌兰夫任首任校长，原高教部综合大学司副司长于北辰任副校长，中国科学院学部委员、著名生物学家、北京大学一级教授、耶鲁大学博士李继侗先生来校执教并任学术副校长。建校初期，党和国家','2026-07-27 22:06:49','2026-08-08 00:12:20');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (61,'辽宁大学','辽宁','沈阳','https://hynu.site/logo/61.png','公办 本科 综合类 双一流 211 辽宁省直属。辽宁大学是一所具备文、史、哲、经、管、法、理、工、医、艺等学科门类的综合性大学，是国家“211工程”重点建设院校和国家“双一流”建设高校，入选教育部基础学科系列“101计划”。学校现有三个校区，即沈阳崇山校区、沈阳蒲河校区和辽阳武圣校区。学校占地面积2222亩，校舍建筑面积73万平方米。辽宁大学源起于1948年11月东北人民政府在沈阳建立的商业专门学校，','2026-07-27 22:06:49','2026-08-08 00:12:20');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (62,'大连海事大学','辽宁','大连','https://hynu.site/logo/62.png','公办 本科 理工类 双一流 211 交通运输部直属。大连海事大学坐落于辽宁省大连市，是一所历史悠久、特色鲜明的高等学府，是交通运输部直属的唯一高校，是国家首批“211工程”和“双一流”建设高校。学校因海而生，其发展历史是中国高等航海教育建设发展成就的缩影。学校肇始于1909年设立的晚清邮传部上海高等实业学堂船政科，为“挽救航权、振兴国运”而萌发初创。学校凭海而兴，在战火纷飞的年代，历尽坎坷，','2026-07-27 22:06:49','2026-08-08 00:12:21');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (63,'延边大学','吉林','延边朝鲜族自治州','https://hynu.site/logo/63.png','公办 本科 综合类 双一流 211 吉林省直属。延边大学（YanbianUniversity）始建于1949年，是中国共产党较早在少数民族地区建立的高校之一，坐落在享有“教育之乡”美誉的吉林省延边朝鲜族自治州首府延吉市，2017年在珲春市设立新校区，学校在教育固边、人才兴边、科技强边、产业富边、学术戍边、文化润边的丰富实践中为党育人、为国育才，是国家“双一流”建设高校、国家“211工程”重点建设大学、西部开发重点建','2026-07-27 22:06:49','2026-08-08 00:12:21');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (64,'东北师范大学','吉林','长春','https://hynu.site/logo/64.png','公办 本科 师范类 双一流 211 教育部直属。巍巍东师，根溯延安1945年10月25日，毛泽东主席接见延安大学校院主要领导干部，指示学校向东北迁移，创办“新型的东北大学”。1946年2月东北大学在辽宁本溪建校，是中国共产党在东北地区创建的第一所综合性大学。1949年7月定址于吉林长春。1950年4月更名为东北师范大学。1996年9月成为首批国家“211工程”重点建设大学。2004年6月经教育部批准设立研究生院。2007年，入选国','2026-07-27 22:06:49','2026-08-08 00:12:22');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (65,'哈尔滨工程大学','黑龙江','哈尔滨','https://hynu.site/logo/65.png','公办 本科 理工类 双一流 211 工业和信息化部直属。哈尔滨工程大学源自1953年创办的中国人民解放军军事工程学院（哈军工），陈赓大将为首任院长，毛泽东主席为学院颁发《训词》，1959年被中共中央确定为全国重点大学。1966年退出军队序列更名为哈尔滨工程学院。1970年在哈军工原址以海军工程系为主体组建哈尔滨船舶工程学院（哈船院），1978年被国务院确定为全国重点大学。1994年更名为哈尔滨工程大学（哈工程）。学校','2026-07-27 22:06:49','2026-08-08 00:12:23');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (66,'东北农业大学','黑龙江','哈尔滨','https://hynu.site/logo/66.png','公办 本科 农林类 双一流 211 黑龙江省直属。东北农业大学是一所“以农科为优势，以生命科学和食品科学为特色，农、工、理、经、管等多学科协调发展”的国家“双一流”建设高校。学校1948年创建于哈尔滨，始称东北农学院，是中国共产党创办的第一所普通高等农业院校，知名教育家、哈尔滨市第一任市长刘达为学校第一任院长。建校以来，先后隶属于东北行政委员会农业部、国家高等教育部、国家农业部、黑龙江','2026-07-27 22:06:49','2026-08-08 00:12:23');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (67,'东北林业大学','黑龙江','哈尔滨','https://hynu.site/logo/67.png','公办 本科 农林类 双一流 211 教育部直属。东北林业大学是一所以林科为优势、林业工程为特色的多学科协调发展的高等学校，地处我国最大国有林区的中心——哈尔滨市，校园占地136公顷，并拥有帽儿山实验林场（帽儿山森林公园）和凉水实验林场（凉水国家级自然保护区）等教学、科研、实习基地，总面积达3.3万公顷。历史沿革1952学校创建于1952年7月，原名东北林学院，是在浙江大学农学院森林系和东北农学院森','2026-07-27 22:06:49','2026-08-08 00:12:24');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (68,'华东理工大学','上海','上海','https://hynu.site/logo/68.png','公办 本科 理工类 双一流 211 教育部直属。华东理工大学原名华东化工学院，1952年由交通大学（上海）、震旦大学（上海）、大同大学（上海）、东吴大学（苏州）、江南大学（无锡）等校化工系合并组建而成，是新中国第一所以化工特色闻名的高等学府。1956年被定为全国首批招收研究生的学校之一，1960年起被中共中央确定为教育部直属的全国重点大学，1993年经国家教委批准更名为华东理工大学，1996年进入国家“211','2026-07-27 22:06:49','2026-08-08 00:12:25');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (69,'东华大学','上海','上海','https://hynu.site/logo/69.png','公办 本科 综合类 双一流 211 教育部直属。东华大学是教育部直属、国家“211工程”、国家“双一流”建设高校。办学历史可追溯至1912年实业家张謇创办的纺织染传习所。1951年建校，时名华东纺织工学院，是新中国第一所纺织高等学府；1960年，被国家教育部确定为全国重点大学；1981年，成为中国首批具有博士、硕士、学士三级学位授予权的大学之一；1985年，更名为中国纺织大学；1998年，被确定为国家“211工程”重','2026-07-27 22:06:49','2026-08-08 00:12:25');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (70,'上海外国语大学','上海','上海','https://hynu.site/logo/70.png','公办 本科 语言类 双一流 211 教育部直属。上海外国语大学（ShanghaiInternationalStudiesUniversity，SISU）创建于1949年12月，是中华人民共和国成立后兴办的第一所高等外语学府，是新中国外语教育的发祥地之一，是教育部直属并与上海市共建、进入国家“211工程”和“双一流”建设的全国重点大学。上外秉承“格高志远、学贯中外”的校训精神和“诠释世界、成就未来”的办学理念，以“服务国家发展、服务人的全面成长、','2026-07-27 22:06:49','2026-08-08 00:12:26');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (71,'上海财经大学','上海','上海','https://hynu.site/logo/71.png','公办 本科 财经类 双一流 211 教育部直属。上海财经大学源于1917年南京高等师范学校创办的商科，著名社会活动家、爱国民主人士杨杏佛任商科主任。1921年，随着以南京高等师范学校为基础建设国立东南大学计划的实施，商科扩充改组并迁址上海，成立国立东南大学分设上海商科大学，这是中国教育史上最早的商科大学，著名教育家郭秉文任校长，著名经济学家马寅初任教务主任。1932年独立建校，定名为国立上海商','2026-07-27 22:06:49','2026-08-08 00:12:26');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (72,'上海大学','上海','上海','https://hynu.site/logo/72.png','公办 本科 综合类 双一流 211 上海市。上海大学是上海市属的综合性研究型大学，是教育部与上海市人民政府共建高校，是国家“211工程”重点建设高校、上海市高水平地方大学建设高校，是国家“双一流”建设高校。建校时期，青云发轫。1922年10月23日成立的上海大学，是中国共产党主导创办并实际领导的第一所正规大学。孙中山、李大钊、陈独秀、毛泽东等悉心关怀，于右任、邓中夏、瞿秋白、蔡和森、任弼时','2026-07-27 22:06:49','2026-08-08 00:12:27');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (73,'中国人民解放军海军军医大学','上海','上海','https://hynu.site/logo/73.png','公办 本科 军事类 双一流 211。中国人民解放军空军军医大学（第四军医大学）是一所培养高、中层次医学专业人才的全国重点大学。学校前身是创建于1941年的八路军晋西北军区卫生学校，1952年被中央军委命名为第四军医大学，1954年与原第五军医大学合并为新的第四军医大学，2017年转隶空军，原空军航空医学研究所并入后组建空军军医大学，2018年，原空军总医院与原空军航空医学研究所合并组建空军特色','2026-07-27 22:06:49','2026-08-08 00:16:05');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (74,'苏州大学','江苏','苏州','https://hynu.site/logo/74.png','公办 本科 综合类 双一流 211 江苏省直属。苏州大学坐落于素有“人间天堂”之称的历史文化名城苏州，是国家“211工程”“2011计划”首批入列高校，是教育部与江苏省人民政府共建“双一流”建设高校、国家航天局共建高校，是江苏省属重点综合性大学。苏州大学前身是SoochowUniversity（东吴大学，1900年创办），开现代高等教育之先河，融中西文化之菁华，是中国最早以现代大学学科体系举办的大学。在中国高等教育','2026-07-27 22:06:49','2026-08-08 00:12:28');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (75,'南京航空航天大学','江苏','南京','https://hynu.site/logo/75.png','公办 本科 理工类 双一流 211 工业和信息化部直属。南京航空航天大学创建于1952年10月，是新中国自己创办的首批航空高等院校之一。1978年被国务院确定为全国重点大学；1981年经国务院批准成为全国首批具有博士学位授予权的高校；1996年进入国家“211工程”建设；2000年经教育部批准设立研究生院；2011年，成为“985工程优势学科创新平台”重点建设高校；2017年，进入国家“双一流”建设序列，现有航空宇航科学与技术、力学','2026-07-27 22:06:49','2026-08-08 00:12:28');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (76,'南京理工大学','江苏','南京','https://hynu.site/logo/76.png','公办 本科 理工类 双一流 211 工业和信息化部直属。南京理工大学是隶属于工业和信息化部的全国重点大学，学校由创建于1953年的新中国军工科技最高学府中国人民解放军军事工程学院（简称“哈军工”）分建而成，历经中国人民解放军炮兵工程学院、华东工程学院、华东工学院等发展阶段，1993年更名为南京理工大学。1995年，学校成为国家“211工程”重点建设高校；2000年，获批成立研究生院；2011年，获批建设“985工程优势学','2026-07-27 22:06:49','2026-08-08 00:12:29');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (77,'河海大学','江苏','南京','https://hynu.site/logo/77.png','公办 本科 综合类 双一流 211 教育部直属。河海大学是一所拥有110年办学历史，以水利为特色、工科为主，多学科协调发展的教育部直属全国重点大学，是国家“双一流”建设、“211工程”重点建设、“985工程优势学科创新平台”建设以及经国家批准设立研究生院的高校。百余年来，学校在治水兴邦的奋斗历程中发展壮大，被誉为“水利高层次创新创业人才培养的摇篮和水利科技创新的重要基地”。学校在南京市、常','2026-07-27 22:06:49','2026-08-08 00:12:29');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (78,'江南大学','江苏','无锡','https://hynu.site/logo/78.png','公办 本科 综合类 双一流 211 教育部直属。江南大学是教育部直属、国家“211工程”重点建设高校和“双一流”建设高校。学校具有悠久的办学历史、厚重的文化积淀，源起1902年创建的三江师范学堂，历经国立中央大学、南京大学等发展时期；1958年南京工学院食品工业系整建制东迁无锡独立建校，成立无锡轻工业学院；1962年无锡纺织工学院并入无锡轻工业学院；1995年更名为无锡轻工大学；2001年无锡轻工大学、江南学','2026-07-27 22:06:49','2026-08-08 00:12:30');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (79,'南京农业大学','江苏','南京','https://hynu.site/logo/79.png','公办 本科 农林类 双一流 211 教育部直属。南京农业大学坐落于钟灵毓秀、虎踞龙蟠的古都南京，是一所以农业和生命科学为优势和特色，农、理、经、管、工、文、法学多学科协调发展的教育部直属全国重点大学，是国家“211工程”重点建设大学、“985优势学科创新平台”和“双一流”建设高校。现任校党委书记王春春，校长陈发棣。南京农业大学前身可溯源至1902年三江师范学堂农学博物科和1914年私立金陵大学农科','2026-07-27 22:06:49','2026-08-08 00:12:30');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (80,'南京师范大学','江苏','南京','https://hynu.site/logo/80.png','公办 本科 师范类 双一流 211 江苏省直属。南京师范大学是国家“双一流”建设高校和江苏高水平大学建设高校。学校的主源可追溯到1902年创办的三江师范学堂，该学堂是中国高等师范教育的发祥地之一。后历经两江优级师范学堂、南京高等师范学校、国立东南大学、国立第四中山大学、江苏大学、国立中央大学、国立南京大学等时期；其另一源头为1888年创办的汇文书院，后发展为金陵大学，1951年与金陵女子文理学','2026-07-27 22:06:49','2026-08-08 00:12:31');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (81,'中国药科大学','江苏','南京','https://hynu.site/logo/81.png','公办 本科 医药类 双一流 211 教育部直属。中国药科大学坐落于古都南京，始建于1936年，是我国历史上第一所由国家创办的药学高等学府。学校为教育部直属、国家“211工程”和“985工程优势学科创新平台”建设高校，是一所以药学为特色的多科性、研究型大学，其中以药学、中药学学科为龙头的药学学科群建设始终保持国内领先水平，素有“中国生物医药人才摇篮”的美誉。2017年，成为国家“双一流”建设高校。历','2026-07-27 22:06:49','2026-08-08 00:12:32');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (82,'安徽大学','安徽','合肥','https://hynu.site/logo/82.png','公办 本科 综合类 双一流 211 安徽省直属。安徽大学1928年创建于时为省会的安庆市，开启安徽现代高等教育之先河。1956年，学校迁址素有“江淮首郡、吴楚要冲，三国故地、包拯家乡”美誉的历史文化名城安徽省省会合肥市。1958年9月16日毛泽东主席亲笔题写“安徽大学”校名，这一天被定为校庆日。学校1996年入选国家“211工程”建设高校，2013年成为教育部与安徽省人民政府共建高校，2017年以来入列国家“双一流”','2026-07-27 22:06:49','2026-08-08 00:12:32');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (83,'合肥工业大学','安徽','合肥','https://hynu.site/logo/83.png','公办 本科 理工类 双一流 211 教育部直属。合肥工业大学是中华人民共和国教育部直属全国重点大学，教育部、工信部和安徽省政府共建高校。学校创建于1945年，1960年被中共中央批准为全国重点大学。刘少奇、朱德、董必武、陈毅、邓小平等老一辈无产阶级革命家先后来校视察指导工作，邓小平同志1979年亲笔为学校题写了校名。学校2005年成为国家“211工程”重点建设高校，2009年成为国家“985工程”优势学科创新平台','2026-07-27 22:06:49','2026-08-08 00:12:33');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (84,'福州大学','福建','福州','https://hynu.site/logo/84.png','公办 本科 理工类 双一流 211 福建省直属。福州大学是国家“双一流”建设高校、国家“211工程”重点建设大学、福建省人民政府与教育部共建高校。学校创建于1958年，现已发展成为一所以工为主、理工结合，理、工、医、经、管、文、法、艺等多学科协调发展的重点大学。建校以来，一代代福大人秉承“明德至诚博学远志”校训，践行以张孤梅同志为代表的艰苦奋斗的创业精神、以卢嘉锡先生为代表的严谨求实的治','2026-07-27 22:06:49','2026-08-08 00:12:33');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (85,'南昌大学','江西','南昌','https://hynu.site/logo/85.png','公办 本科 综合类 双一流 211 江西省直属。南昌大学是国家“双一流”建设高校、教育部与江西省部省合建高校、江西省一流大学整体建设高校。学校地处“英雄城”南昌市，拥有前湖、青山湖、东湖3个校区，其中前湖主校区占地面积4260余亩，校舍建筑面积149万余平方米，总体占地面积5460余亩，校舍建筑总体面积202万余平方米。学校前身江西医学院、江西大学和江西工业大学分别溯源于1921年创建的江西公立医学专门','2026-07-27 22:06:49','2026-08-08 00:12:34');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (86,'中国石油大学（华东）','山东','青岛','https://hynu.site/logo/86.png','公办 本科 理工类 双一流 211 教育部直属。中国石油大学（华东）是教育部直属全国重点大学，是国家“211工程”重点建设和开展“985工程优势学科创新平台”建设并建有研究生院的高校之一。学校是教育部和五大能源企业集团公司、教育部和山东省人民政府共建的高校，是石油石化高层次人才培养的重要基地，被誉为“石油科技、管理人才的摇篮”，现已成为一所以工为主、石油石化特色鲜明、多学科协调发展的大','2026-07-27 22:06:49','2026-08-08 00:12:35');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (87,'郑州大学','河南','郑州','https://hynu.site/logo/87.png','公办 本科 综合类 双一流 211 河南省直属。郑州大学（简称郑大，英文简称：ZZU）由河南省人民政府兴办，法定住所地为河南省郑州市科学大道100号。学校总占地面积8500余亩，主校区位于郑州市科学大道100号，南校区位于郑州市大学北路75号，北校区位于郑州市文化路97号，东校区位于郑州市大学北路40号。学校面向全国招生，现有全日制普通本科生4.4万余人、研究生近3万人，以及来自88个国家的留学生2300余人。郑州大','2026-07-27 22:06:49','2026-08-08 00:12:35');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (88,'华中农业大学','湖北','武汉','https://hynu.site/logo/88.png','公办 本科 农林类 双一流 211 教育部直属。华中农业大学是中国高等农业教育起点之一。学校前身是清朝光绪年间由湖广总督张之洞于1898年创办的湖北农务学堂。几经演变，1952年，武汉大学农学院和湖北农学院的全部系科以及中山大学等6所综合性大学农学院的部分系科组建成立华中农学院。1979年，经国务院批准列为全国重点大学，直属农业部。1985年，更名为华中农业大学。2000年，由农业部划转教育部直属领导。2005','2026-07-27 22:06:49','2026-08-08 00:12:36');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (89,'华中师范大学','湖北','武汉','https://hynu.site/logo/89.png','公办 本科 师范类 双一流 211 教育部直属。华中师范大学位于九省通衢的湖北省武汉市，坐落在武昌南湖之滨的桂子山上，占地面积120余万平方米，是教育部直属重点综合性师范大学，国家“211工程”重点建设大学，国家教师教育“985优势学科创新平台”建设高校，国家“双一流”建设高校。【学脉传承博雅为宗】学校办学历史悠久。溯源于1903年创办的文华书院大学部（始于1871年创办的文华书院，1924年改名为华中大','2026-07-27 22:06:49','2026-08-08 00:12:36');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (90,'武汉理工大学','湖北','武汉','https://hynu.site/logo/90.png','公办 本科 理工类 双一流 211 教育部直属。武汉理工大学是教育部直属全国重点大学，是首批列入国家“211工程”和“双一流”建设高校，是教育部和交通运输部等部委共建高校。学校办学历史起源于1898年建立的湖北工艺学堂，办学127年特别是近70年来，学校共培养了70余万名高级专门人才，是教育部直属高校中为建材建工、交通、汽车三大行业培养人才规模最大的学校，是我国“三大行业”高层次人才培养和科技创新','2026-07-27 22:06:49','2026-08-08 00:12:37');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (91,'中南财经政法大学','湖北','武汉','https://hynu.site/logo/91.png','公办 本科 财经类 双一流 211 教育部直属。中南财经政法大学是教育部直属的全国重点大学，是国家“211工程”和“985工程优势学科创新平台”重点建设高校，是国家“双一流”建设高校，是教育部、财政部和湖北省共建高校。历史源远，弦歌不辍。学校前身是1948年以邓小平为第一书记的中共中央中原局创建，并由第二书记陈毅担任筹备委员会主任的中原大学。全国高等院校调整期间，以中原大学财经学院、政法学院','2026-07-27 22:06:49','2026-08-08 00:12:38');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (92,'湖南师范大学','湖南','长沙','https://hynu.site/logo/92.png','公办 本科 师范类 双一流 211 湖南省直属。湖南师范大学创建于1938年，位于历史文化名城长沙，是国家“211工程”重点建设的大学，国家“双一流”建设高校，教育部与湖南省重点共建“双一流”建设高校，教育部普通高等学校本科教学工作水平评估优秀高校。学校占地近3000亩，建筑面积147万平方米。主校区西偎麓山，东濒湘江，风光秀丽，是全国绿化“400佳”单位之一。学校设有24个学院，现有本科招生专业87个，','2026-07-27 22:06:49','2026-08-08 00:12:38');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (93,'暨南大学','广东','广州','https://hynu.site/logo/93.png','公办 本科 综合类 双一流 211 中央统战部直属。暨南大学是中央统战部直属的“双一流”建设高校，由中央统战部、教育部、广东省人民政府共同建设。学校是中国第一所由政府创办的华侨学府，素有“华侨最高学府”之美誉。2018年10月24日，习近平总书记亲临学校考察并发表重要讲话，殷切嘱托暨南大学擦亮金字招牌，为海外侨胞归国求学创造更好条件，把中华优秀文化传播到五洲四海。百廿暨南，文脉悠长。“暨南”之','2026-07-27 22:06:49','2026-08-08 00:12:39');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (94,'华南师范大学','广东','广州','https://hynu.site/logo/94.png','公办 本科 师范类 双一流 211 广东省直属。华南师范大学是国家“双一流”建设高校、“211工程”重点建设大学、广东省和教育部共建高校及广东省高水平大学重点建设高校。现有“三校区四校园”，包括广州校区石牌校园、大学城校园，佛山校区南海校园和汕尾校区滨海校园。学校设4个学部、35个学院、9个研究院（中心）。学校办学史可溯源至1888年创建的格致书院、1905年创建的两广师范学堂和1921年创建的广州市立','2026-07-27 22:06:49','2026-08-08 00:12:39');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (95,'海南大学','海南','海口','https://hynu.site/logo/95.png','公办 本科 综合类 双一流 211 海南省直属。海南大学是国家“双一流”建设高校,教育部、海南省“部省合建”高校海南大学是国家“双一流”建设高校,教育部与海南省“部省合建”高校。2018年4月13日，习近平总书记在庆祝海南建省办经济特区30周年大会上的重要讲话中指出“要支持海南大学创建世界一流学科”，为学校发展提供了根本遵循。根据《软科中国大学发展速度排名》，2019-2022年学校总增速位列全国高校第一','2026-07-27 22:06:49','2026-08-08 00:12:40');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (96,'广西大学','广西','南宁','https://hynu.site/logo/96.png','公办 本科 综合类 双一流 211 广西壮族自治区。广西大学坐落于素有“中国绿城”之称的广西首府南宁，是广西唯一的国家“211工程”建设高校、“双一流”建设高校、教育部与广西壮族自治区人民政府“部区合建”高校。广西大学1928年成立于广西梧州，1939年成为国立广西大学，首任校长是被誉为“一代宗师”、与蔡元培并称“北蔡南马”的我国著名教育家、科学家、民主革命家马君武博士，李四光、陈望道、李达、陈寅','2026-07-27 22:06:49','2026-08-08 00:12:40');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (97,'西南交通大学','四川','成都','https://hynu.site/logo/97.png','公办 本科 理工类 双一流 211 教育部直属。西南交通大学是教育部直属全国重点大学，国家首批“双一流”“211工程”“985工程优势学科创新平台”“2011协同创新计划”重点建设高校，设有研究生院。坐落于中国历史文化名城、国家中心城市、“成渝地区双城经济圈”核心城市——成都。学校1896年创建于山海关，始称“北洋铁路官学堂”（ImperialChineseRailwayCollege），是中国第一所工程教育高等学府，中国土木工程、矿','2026-07-27 22:06:49','2026-08-08 00:12:41');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (98,'西南财经大学','四川','成都','https://hynu.site/logo/98.png','公办 本科 财经类 双一流 211 教育部直属。西南财经大学是教育部直属全国重点大学，国家首批“双一流”建设高校。学校坐落于中国历史文化名城——“天府之国”成都，有光华、柳林两校区，辖地2300余亩。校园湖光柳影，芳草绿树，翩翩学者，蔚为大观，是著名的“园林式院校”，乃读书治学的理想园地。学校始于1925年在上海创建的光华大学。1938年，因抗战内迁建立光华大学成都分部。1952-1953年，先后汇聚西南','2026-07-27 22:06:49','2026-08-08 00:12:42');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (99,'四川农业大学','四川','成都','https://hynu.site/logo/99.png','公办 本科 农林类 双一流 211 四川省直属。四川农业大学是一所以生物科技为特色，农业科技为优势，多学科协调发展的国家“211工程”重点建设大学和国家“双一流”建设高校，也是教育部本科教学工作水平评估优秀高校。现任党委书记刘登才教授、校长吴德教授。办学历史悠久、资源丰富。前身是1906年创办的四川通省农业学堂，此后历经四川高等农业学校(1912年)、四川公立农业专门学校(1914年)、公立四川大学农科','2026-07-27 22:06:49','2026-08-08 00:12:42');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (100,'贵州大学','贵州','贵阳','https://hynu.site/logo/100.png','公办 本科 综合类 双一流 211 贵州省直属。贵州大学创建于1902年，历经贵州大学堂、省立贵州大学、国立贵州农工学院、国立贵州大学等时期，1950年10月定名为贵州大学。1951年11月，毛泽东主席亲笔题写“贵州大学”校名。1997年8月，与贵州农学院等院校合并。2004年8月，与贵州工业大学合并。历经120余年的建设发展，先后成为国家“211工程”大学、国家“双一流”建设高校，教育部、贵州省人民政府“部省合建”高校','2026-07-27 22:06:49','2026-08-08 00:12:43');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (101,'云南大学','云南','昆明','https://hynu.site/logo/101.png','公办 本科 综合类 双一流 211 云南省直属。云南大学始建于1922年，1923年正式开学，时为私立东陆大学，1934年更名为省立云南大学，1938年改为国立云南大学，是我国西部边疆最早建立的综合性大学之一。1937年，著名数学家、教育家熊庆来出任校长，一大批著名学者受聘到校任教，奠定了学校较高的发展基础和深厚的学术底蕴，开创了云大办学历史上的第一个辉煌时期。20世纪40年代，云南大学已发展成为一所包括文、','2026-07-27 22:06:49','2026-08-08 00:12:44');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (102,'西藏大学','西藏','拉萨','https://hynu.site/logo/102.png','公办 本科 综合类 双一流 211 西藏自治区。西藏大学坐落于西藏自治区首府拉萨，是新中国在雪域高原创办的第一所综合性大学，是一所具有光荣传统和光辉历史的大学，是西藏自治区唯一一所国家“211工程”重点建设大学、“双一流”建设高校、部区合建高校。学校办学历史可追溯到1951年中国人民解放军进藏部队创办的藏文干部训练班，历经西藏军区干部学校、西藏地方干部学校、西藏行政干部学校等发展阶段。1965','2026-07-27 22:06:49','2026-08-08 00:12:44');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (103,'西北大学','陕西','西安','https://hynu.site/logo/103.png','公办 本科 综合类 双一流 211 陕西省直属。西北大学肇始于1902年的陕西大学堂和京师大学堂速成科仕学馆。1912年始称西北大学。1923年改为国立西北大学。1937年西迁来陕的国立北平大学、北平师范大学、北洋工学院和北平研究院等组成国立西安临时大学，1938年改为国立西北联合大学，1939年复称国立西北大学。新中国成立后为教育部直属综合大学。1950年复名西北大学。1958年改隶陕西省主管。1978年被确定为全国重点大','2026-07-27 22:06:49','2026-08-08 00:12:45');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (104,'西安电子科技大学','陕西','西安','https://hynu.site/logo/104.png','公办 本科 理工类 双一流 211 教育部直属。西安电子科技大学是以电子与信息学科为特色，工、理、管、文、经等多学科协调发展的全国重点大学，直属教育部。目前有长安、雁塔两个校区，总占地面积3944.8亩，校舍建筑面积159.06万平方米。学校前身是1931年诞生于江西瑞金的中央革命军事委员会无线电学校，是毛泽东等老一辈革命家亲手创建的我党我军第一所工程技术学校，跟随中国工农红军经历了长征并在长征路上','2026-07-27 22:06:49','2026-08-08 00:12:45');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (105,'长安大学','陕西','西安','https://hynu.site/logo/105.png','公办 本科 理工类 双一流 211 教育部直属。长安大学直属国家教育部，是国家首批“211工程”重点建设大学、国家“985优势学科创新平台”建设高校、国家“双一流”建设高校。学校创建于新中国百业待兴之时，壮大于改革浪潮迭起之际，兴盛于高等教育强国大势之中，与共和国同向同行七十余载。自1951年起，学校前身西安公路交通大学、西安工程学院、西北建筑工程学院相继成立，1956年开始招收来华留学生，1978年','2026-07-27 22:06:49','2026-08-08 00:12:46');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (106,'陕西师范大学','陕西','西安','https://hynu.site/logo/106.png','公办 本科 师范类 双一流 211 教育部直属。陕西师范大学位于古都西安，是教育部直属重点大学。学校前身是1944年成立的陕西省立师范专科学校，1954年更名为西安师范学院，1960年与陕西师范学院合并，定名为陕西师范大学。1978年成为教育部直属师范大学，2005年入选全国“211工程”建设高校，2008年入选国家“985工程”教师教育优势学科创新平台建设高校，2017年入选国家首批“双一流”建设高校，全面开启扎根中国大','2026-07-27 22:06:49','2026-08-08 00:12:46');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (107,'第四军医大学','陕西','西安','https://hynu.site/logo/107.png','公办 本科 军事类 双一流 211。海军军医大学地处上海，创建于1949年,时称华东军区人民医学院，1951年定名为第二军医大学。2015年由原总后勤部转隶中央军委训练管理部。2017年转隶海军，组建海军军医大学，对外可称第二军医大学。学校是一所培养卫生事业专门人才的全国重点医科大学。近70年来，学校始终秉承“求实、创新、严谨、献身”的校训，逐步形成了以“博雅、仁爱、笃行”为精神内核的“红十','2026-07-27 22:06:49','2026-08-08 00:16:05');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (108,'青海大学','青海','西宁','https://hynu.site/logo/108.png','公办 本科 综合类 双一流 211 青海省直属。青海大学坐落于高原古城—夏都西宁。学校前身为青海工学院，始建于1958年。1960年11月，与青海农牧学院、青海医学院、青海财经学院合并为青海大学，1969年被撤销。1971年恢复青海工农学院，设有工、农两大学科。1988年恢复青海大学。1997年10月，青海畜牧兽医学院并入青海大学。2001年1月，青海省农林科学院、青海省畜牧兽医科学院、青海财经职业学院整建制划归青海大学','2026-07-27 22:06:49','2026-08-08 00:12:47');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (109,'宁夏大学','宁夏','银川','https://hynu.site/logo/109.png','公办 本科 综合类 双一流 211 宁夏回族自治区。宁夏大学是教育部与宁夏回族自治区人民政府合建高校，国家“双一流”建设高校，国家“211工程”重点建设高校。宁夏大学始建于1958年。1997年12月，宁夏大学与原宁夏工学院、银川师专（含宁夏教育学院）合并；2002年2月，与宁夏农学院合并，组建了新的宁夏大学；2014年4月，宁夏大学中卫校区成立；2017年9月，入选国家“双一流”建设高校；2018年2月，成为教育部与宁夏回','2026-07-27 22:06:49','2026-08-08 00:12:47');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (110,'新疆大学','新疆','乌鲁木齐','https://hynu.site/logo/110.png','公办 本科 综合类 双一流 211 新疆维吾尔自治区。发展理念及办学目标新疆大学始终秉承“团结、紧张、质朴、活泼”的校训，坚守“开拓、进取、求实、创新”的优良校风，坚持“立足新疆、服务西部、面向全国、辐射中亚”的办学定位，坚持“以抗大精神育人，为兴疆固边服务”的办学特色，坚持“建强工科、优化理科、繁荣文科、促进交叉”的学科建设理念和办学优势，力争到2035年全面建成“丝绸之路经济带上特色鲜','2026-07-27 22:06:49','2026-08-08 00:12:48');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (111,'石河子大学','新疆','自治区直辖县级行政区划','https://hynu.site/logo/111.png','公办 本科 综合类 双一流 211 新疆生产建设兵团。历史沿革1949中国人民解放军解放新疆的进军途中，第一兵团司令员王震指示创办了中国人民解放军第一兵团卫生学校（1978年发展为石河子医学院），成为石河子大学的前身。1958兵团党委创办兵团农学院（1979年改名石河子农学院），1959年创办了兵团会计培训队（1987年发展为兵团经济专科学校），1960年创建了兵团师范专科学校。1996石河子医学院、石河子农学院、兵团经济专科','2026-07-27 22:06:49','2026-08-08 00:12:49');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (112,'上海科技大学','上海','上海','https://hynu.site/logo/112.png','公办 本科 理工类 双一流 上海市 中国科学院。上海科技大学（中文简称：上科大，英文全称：ShanghaiTechUniversity，英文缩写：ShanghaiTech）是由上海市人民政府与中国科学院共同举办、共同建设，由上海市人民政府负责日常管理的全日制普通高等学校。自建立以来，学校努力建设和发展成为一所小规模、高水平、国际化的研究型、创新型大学。2022年2月入选第二轮“双一流”建设高校。上科大的孕育和成长始终与我国的改革','2026-07-27 22:06:49','2026-08-08 00:12:49');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (113,'南方科技大学','广东','深圳','https://hynu.site/logo/113.png','公办 本科 理工类 双一流 广东省直属。南方科技大学（简称：南科大）是深圳在中国高等教育改革发展的时代背景下创建的一所高起点、高定位的公办新型研究型大学。2022年2月14日，教育部等三部委公布第二轮“双一流”建设高校及建设学科名单，南方科技大学及数学学科入选“双一流”建设高校及建设学科名单。学校借鉴世界一流理工科大学的学科设置和办学模式，以理、工、医为主，兼具商科和特色人文社科','2026-07-27 22:06:49','2026-08-08 00:12:50');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (114,'上海体育学院','上海','上海','https://hynu.site/logo/114.png','公办 本科 体育类 双一流。上海体育大学创建于1952年，原名华东体育学院，1956年更名为上海体育学院，是新中国成立后国家创建的第一所体育高等学府。学校原为国家体委直属高校，2001年起，由国家体育总局和上海市人民政府共建。2017年以来，连续入选国家“双一流”建设单位。2023年6月，经教育部批准，更名为上海体育大学。学校坚持社会主义办学方向，秉持“身心一统，兼蓄竞攀”校训，承载“','2026-07-27 22:06:49','2026-08-08 00:14:45');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (115,'南京信息工程大学','江苏','南京','https://hynu.site/logo/115.png','公办 本科 综合类 双一流 江苏省直属。南京信息工程大学是国家“双一流”建设高校，是江苏高水平大学建设高峰计划A类建设高校。学校前身为南京气象学院，始建于1960年，隶属原中央（军委）气象局，是新中国创办的第一所气象本科院校，被誉为“气象人才的摇篮”。学校1978年被列入首批88所全国重点大学，1993年获博士学位授予权，2000年划转江苏省人民政府主管，2004年更名为南京信息工程大学。2007年以来，','2026-07-27 22:06:49','2026-08-08 00:12:51');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (116,'南京邮电大学','江苏','南京','https://hynu.site/logo/116.png','公办 本科 理工类 双一流 江苏省直属。南京邮电大学是一所红色基因厚重、信息特色鲜明的国家“双一流”建设高校和江苏高水平大学高峰计划A类建设高校，是新中国第一所邮电学校，被誉为“华夏IT英才的摇篮”。学校前身是1942年诞生于八路军山东抗日根据地的战邮干训班，后定名为华东邮电学校，是我党、我军早期系统培养通信人才的学校之一；1949年随解放大军南下迁址南京；1950年组建为邮电部南京邮电学','2026-07-27 22:06:49','2026-08-08 00:12:51');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (117,'南京林业大学','江苏','南京','https://hynu.site/logo/117.png','公办 本科 农林类 双一流 江苏省直属。南京林业大学是一所以林科为优势，以服务国家生态文明建设为引领，理、工、农、文、管、经、法、艺等多学科协调发展的高水平研究型大学。学校是江苏省人民政府与教育部、国家林业和草原局共建高校，国家“双一流”建设高校，江苏省高水平大学建设高峰计划A类建设高校。学校前身可溯源至1902年创立的三江师范学堂和1910年建立的金陵大学堂。1952年，全国高校院系调','2026-07-27 22:06:49','2026-08-08 00:12:52');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (118,'广州医科大学','广东','广州','https://hynu.site/logo/118.png','公办 本科 医药类 双一流 广东省直属。广州医科大学创办于1958年，是国家“双一流”建设高校、全国首批“卓越医生教育培养计划”试点高校和广东省高水平大学重点建设高校。现有2个校区（番禺校区和越秀校区），占地面积65.29万平方米，建筑面积65.22万平方米。学校全面落实立德树人根本任务，着力构建高质量人才培养体系。现有全日制在校学生1.6万余人，其中研究生6千余人、本科生约1万人。拥有一级学科博','2026-07-27 22:06:49','2026-08-08 00:12:52');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (119,'华南农业大学','广东','广州','https://hynu.site/logo/119.png','公办 本科 综合类 双一流 广东省直属。华南农业大学是国家“双一流”建设高校。校园坐落在素有“花城”美誉的广州市，土地总面积8211亩，其中天河五山校部4407亩，增城教学科研基地3804亩。学校建筑总面积140万平方米，自然景色与人文景观交相辉映，形成了“五湖四海一片林”的优美环境。学校办学历史可追溯至始创于1909年的广东全省农事试验场暨附设农业讲习所。1952年全国高校院系调整时，由中山大学农学','2026-07-27 22:06:49','2026-08-08 00:12:53');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (120,'宁波大学','浙江','宁波','https://hynu.site/logo/120.png','公办 本科 综合类 双一流 浙江省直属。宁波大学1986年由世界船王包玉刚先生捐资创立，邓小平同志题写校名，建校之初由北京大学、复旦大学、浙江大学、中国科学技术大学、原杭州大学对口援建，高起点开启办学历程。1996年原宁波大学、宁波师范学院和浙江水产学院宁波分院合并组建新宁波大学。习近平总书记主政浙江期间曾指示：“努力把宁波大学建设成国内一流的地方综合性大学，为浙江建设创新型省份，','2026-07-27 22:06:49','2026-08-08 00:12:53');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (121,'中国科学院大学','北京','北京','https://hynu.site/logo/121.png','公办 本科 综合类 双一流 中国科学院。中国科学院大学简称“国科大”，是一所以科教融合为办学模式、研究生教育为办学主体、精英化本科教育为办学特色的创新型大学。国科大的研究生教育，发端于中国科学院的人才培养。1950年，中国科学院启动研究实习员的招考和培养工作。1951年6月，中国科学院与中央教育部联合发布《中国科学院所属研究机构、中央教育部所属高等学校研究部一九五一年暑期招收研究实','2026-07-27 22:06:49','2026-08-08 00:12:54');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (122,'外交学院','北京','北京','https://hynu.site/logo/122.png','公办 本科 语言类 双一流 外交部直属。外交学院是以服务中国外交事业为宗旨，培养一流外交外事人才的小规模、高层次、特色鲜明的外交部唯一直属高校。在周恩来总理倡议下，经党中央、毛主席批准，于1955年9月10日正式成立。周总理为我院亲笔题写校名，时任国务院副总理兼外交部部长陈毅元帅担任首任院长。我院自创办以来一直得到党和国家领导人的亲切关怀。周恩来总理、陈毅副总理、钱其琛副总理，以','2026-07-27 22:06:49','2026-08-08 00:12:54');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (123,'中国人民公安大学','北京','北京','https://hynu.site/logo/123.png','公办 本科 政法类 双一流 公安部直属。历史沿革中国人民公安大学是公安部直属的国家“双一流”建设高校（与公安部高级警官学院一体化运行），创始于1948年中共中央在西柏坡举办的华北保卫干部训练班，是全国公安系统第一个开展普通高等学历教育、硕士研究生培养和唯一开展博士研究生教育的高等学府，也是学科专业最齐全、办学规模最大、教育层次最完备、唯一入选国家“双一流”建设的公安院校。建校','2026-07-27 22:06:49','2026-08-08 00:12:55');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (124,'中央美术学院','北京','北京','https://hynu.site/logo/124.png','公办 本科 艺术类 双一流 教育部直属。中央美术学院是中华人民共和国教育部直属的唯一一所高等美术学校。现设有中国画学院、书法学院、油画系、版画系、雕塑系、壁画系、造型学科基础部、实验艺术与科技艺术学院、人文学院、设计学院、建筑学院、城市设计学院、艺术管理与教育学院、（中法）艺术与设计管理学院、修复学院、马克思主义学院十六个专业院系，并设有研究生院、继续教育学院和附属中等','2026-07-27 22:06:49','2026-08-08 00:12:56');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (125,'中央音乐学院','北京','北京','https://hynu.site/logo/125.png','公办 本科 艺术类 双一流 211 教育部直属。中央音乐学院是新中国成立后创办的第一所高等专业音乐院校，于1949年10月在天津成立，由华北大学第三部音乐科、鲁迅艺术学院音工团、南京国立音乐院、国立北平艺术专科学校音乐系和上海（香港）中华音乐院组成，1950年6月17日补行成立典礼。1952年燕京大学音乐系并入。1958年自天津迁至北京现址。1960年被中央确定为国家重点大学，1981年被国务院批准为全国高校首批博士','2026-07-27 22:06:49','2026-08-08 00:12:56');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (126,'中国音乐学院','北京','北京','https://hynu.site/logo/126.png','公办 本科 艺术类 双一流 北京市。中国音乐学院建立于1964年，是国家“双一流”建设院校、北京市“高水平研究型大学”建设院校、“全球音乐教育联盟”秘书处学校。学校坚持党的领导，坚持社会主义办学方向，坚守弘扬中华优秀传统音乐文化、发展社会主义民族新音乐的办学初心，以“承国学、扬国韵、育国器、强国音”为办学理念，以“仁爱、诚信、博学、精艺”为校训，以建设中国特色世界一流高等','2026-07-27 22:06:49','2026-08-08 00:12:57');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (127,'中央戏剧学院','北京','北京','https://hynu.site/logo/127.png','公办 本科 艺术类 双一流 教育部直属。中央戏剧学院是新中国第一所戏剧教育高等学校，是教育部直属院校，是中国戏剧影视艺术教育的最高学府，是国家确定的“双一流”建设高校，是中国高等戏剧教育联盟总部、亚洲戏剧教育研究中心总部和世界戏剧教育联盟秘书处所在地，是世界著名艺术院校。中央戏剧学院的历史可以溯源至1938年4月10日成立的延安鲁迅艺术学院，至今已经有80余年的历史。1949年12月，中央','2026-07-27 22:06:49','2026-08-08 00:12:57');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (128,'北京协和医学院','北京','北京','https://hynu.site/logo/128.png','公办 本科 医药类 双一流 国家卫生健康委员会。中国医学科学院成立于1956年，北京协和医学院成立于1917年，中国医学科学院北京协和医学院自1957年起实行院校合一的管理体制，是我国最高医学研究机构和领衔医学教育机构。院校始终牢记初心使命，以引领我国医学科技教育发展和维护人民健康为己任，教育人才辈出，科研硕果累累，医疗领衔行业，为我国现代科学医学体系的建立和发展做出了重要贡献。建立之初，北京','2026-07-27 22:06:49','2026-08-08 00:12:58');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (129,'首都师范大学','北京','北京','https://hynu.site/logo/129.png','公办 本科 师范类 双一流 北京市。首都师范大学建于1954年，办学历史可追溯至1905年成立的通州师范，是国家“双一流”建设高校、北京市与教育部“省部共建”高校。学校现有学科专业涵盖哲学、经济学、法学、教育学、文学、历史学、理学、工学、管理学、艺术学等，七十多年来已培养各类高级专门人才二十余万名，是北京市人才培养的重要基地。习近平总书记曾于2009年来校调研，他指出：“首都师大是','2026-07-27 22:06:49','2026-08-08 00:12:58');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (130,'上海中医药大学','上海','上海','https://hynu.site/logo/130.png','公办 本科 医药类 双一流 上海市。上海中医药大学成立于1956年，是新中国诞生后国家首批建立的四所中医药高等院校之一，是教育部、国家中医药管理局与上海市人民政府共建的高校，是“双一流”学科建设高校，也是上海市重点建设的高水平大学。学校位于浦东新区张江科学城核心板块，占地500余亩，教学设施齐全、环境优美。学校以主动对接国家战略、对接服务具有全球影响力的科技创新中心建设为己任','2026-07-27 22:06:49','2026-08-08 00:12:59');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (131,'上海海洋大学','上海','上海','https://hynu.site/logo/131.png','公办 本科 农林类 双一流 上海市。上海海洋大学是多科性应用研究型大学，上海市人民政府与国家海洋局、农业农村部共建高校。2017年9月入选国家“世界一流学科建设高校”。2022年2月入选第二轮“双一流”建设高校及建设学科名单。学校校训：勤朴忠实，1914年9月1日定立。创校初心：渔界所至，海权所在也。办学传统：把论文写在祖国的江河湖泊和世界的大洋大海上。学校前身是张謇、黄炎培创建于1912年的','2026-07-27 22:06:49','2026-08-08 00:13:00');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (132,'上海音乐学院','上海','上海','https://hynu.site/logo/132.png','公办 本科 艺术类 双一流 上海市。上海音乐学院（ShanghaiConservatoryofMusic）是中国现代专业音乐教育的奠基者和孵化器，国家首批“双一流”建设高校，作为中国音乐教育的杰出代表在海内外享有盛誉，被誉为“音乐家的摇篮”。上海音乐学院前身为国立音乐院，由蔡元培先生和萧友梅先生于1927年11月27日在上海创办，首任院长蔡元培先生，是中国第一所独立建制的国立高等音乐学府，以“援西立中，化用为体”','2026-07-27 22:06:49','2026-08-08 00:13:00');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (133,'南京中医药大学','江苏','南京','https://hynu.site/logo/133.png','公办 本科 医药类 双一流 江苏省直属。南京中医药大学创建于1954年，是国家“双一流”建设高校、江苏高水平大学高峰计划A类建设高校，教育部、江苏省人民政府与国家中医药管理局共建高校。学校是全国建校最早的高等中医药院校之一，为新中国高等中医药教育培养输送了第一批师资、编撰了第一套教材、制订了第一版教学大纲，为新中国高等中医药教育模式的确立和推广作出了开创性贡献，被誉为“高等中医','2026-07-27 22:06:49','2026-08-08 00:13:01');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (134,'南京医科大学','江苏','南京','https://hynu.site/logo/134.png','公办 本科 医药类 双一流 江苏省直属。南京医科大学是国家“双一流”建设高校，首批教育部、国家卫生健康委员会与江苏省人民政府共建医学院校，教育部高水平公共卫生学院建设高校，江苏高水平大学建设高峰计划A类建设高校。学校创建于1934年，时名江苏省立医政学院，抗战时期更名为国立江苏医学院。1957年，由镇江迁至南京，更名为南京医学院。1962年，被列为全国首批六年制医药院校。1981年，被批准为全','2026-07-27 22:06:49','2026-08-08 00:13:02');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (135,'天津中医药大学','天津','天津','https://hynu.site/logo/135.png','公办 本科 医药类 双一流 天津市。天津中医药大学始建于1958年（原名天津中医学院）。2020年成为天津市人民政府、教育部、国家中医药管理局共建高校，2017年进入国家“双一流”建设高校序列，是原国家教委批准的唯一一所中国传统医药国际学院，世界中医药学会联合会教育指导委员会主任委员单位。学校有静海团泊校区、南开玉泉路校区。团泊校区占地2100余亩，建有天津中药植物园、天津市中医药博物馆','2026-07-27 22:06:49','2026-08-08 00:13:02');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (136,'天津工业大学','天津','天津','https://hynu.site/logo/136.png','公办 本科 综合类 双一流 天津市。天津工业大学是教育部与天津市共建、天津市重点建设的全日制普通高等学校。学校办学历史源于1912年创建的北京工业专门学校机织科，2000年更名为天津工业大学，2017年、2022年连续进入国家“双一流”建设高校序列，2018年获批国防科工局与天津市共建高校，是我国最早开展纺织高等教育的学府之一，现已发展成为一所以工为主，工、理、文、管、经、法、艺、医协调发展的','2026-07-27 22:06:49','2026-08-08 00:13:03');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (137,'成都理工大学','四川','成都','https://hynu.site/logo/137.png','公办 本科 理工类 双一流 四川省直属。成都理工大学是国家首批“双一流”建设高校。其前身是创办于1956年的成都地质勘探学院，是共和国建国初期的三所地质院校之一。1958年更名为成都地质学院，1993年更名为成都理工学院，2001年更名为成都理工大学。学校先后由地质部、地质矿产部、国土资源部直属，至2000年划转地方。学校2010年成为国土资源部与四川省人民政府共建高校，2017年成为国家首批“双一流”建设','2026-07-27 22:06:49','2026-08-08 00:13:03');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (138,'成都中医药大学','四川','成都','https://hynu.site/logo/138.png','公办 本科 医药类 双一流 四川省直属。成都中医药大学建校于1956年，是新中国最早建立的四所中医药高等院校之一。原名成都中医学院，1995年更名为成都中医药大学。历经近70年建设发展，已成为一所以中医药学科为主体、医药健康相关学科专业相互支撑、协调发展的特色鲜明的高水平中医药大学，是教育部、四川省人民政府、国家中医药管理局共建高校，国家“双一流”建设高校，国家高等学校学科创新引智基','2026-07-27 22:06:49','2026-08-08 00:13:04');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (139,'西南石油大学','四川','成都','https://hynu.site/logo/139.png','公办 本科 综合类 双一流 四川省直属。西南石油大学是新中国创建的第二所石油本科院校，是一所中央与地方共建、以四川省人民政府管理为主的高等学校。2013年，学校入选“国家中西部高校基础能力建设工程”，成为入选该工程的100所高校之一。2017年9月，入选国家首批“双一流”世界一流学科建设高校。2022年2月，入选国家第二轮“双一流”建设高校及建设学科名单。20世纪50年代中后期，我国石油工业相当落','2026-07-27 22:06:49','2026-08-08 00:13:05');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (140,'湘潭大学','湖南','湘潭','https://hynu.site/logo/140.png','公办 本科 综合类 双一流 湖南省直属。湘潭大学简称“湘大”，是一代伟人毛泽东同志亲自倡办的综合性全国重点大学、国家“双一流”建设高校。学校创办于1958年，同年9月10日，毛泽东同志亲笔题写“湘潭大学”校名，并亲切嘱托“一定要把湘潭大学办好”。1974年，邓小平、李先念等中央领导同志批准湘潭大学复校。1978年，学校被国务院确定为全国16所文理工综合性重点大学之一。1981年，学校成为全国首批硕','2026-07-27 22:06:49','2026-08-08 00:13:05');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (141,'河南大学','河南','郑州','https://hynu.site/logo/141.png','公办 本科 综合类 双一流 河南省直属。河南大学是一所办学历史悠久、学科门类齐全、专业特色鲜明、文化底蕴深厚的国家“双一流”建设高校。河南大学创立于1912年，始名河南留学欧美预备学校，首任校长为林伯襄先生，校园选建于河南贡院旧址之上。后历经中州大学、国立开封中山大学（又称国立第五中山大学）、省立河南大学等阶段，1942年升格为国立河南大学。1952年院系调整，部分院系或独立建校或并入','2026-07-27 22:06:49','2026-08-08 00:13:06');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (142,'山西大学','山西','太原','https://hynu.site/logo/142.png','公办 本科 综合类 双一流 山西省直属。山西大学是中国办学历史最悠久的高等学府之一，是国家“双一流”建设高校，是教育部和山西省人民政府共同建设的部省合建大学。学校创办于1902年，初名山西大学堂。其悠远的文脉可以上溯至明清时期的三立书院、晋阳书院和令德堂书院。学校创办的山西大学堂译书院是中国近代大学创办的第二所译书院，有力促进了中西文化交流。二十世纪二三十年代，山西大学名宿云','2026-07-27 22:06:49','2026-08-08 00:13:06');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (143,'东北财经大学','辽宁','大连','https://hynu.site/logo/143.png','公办 本科 财经类 辽宁省直属。东北财经大学以“培育卓越财经人才，服务经济社会发展”为使命，是一所突出经济学、管理学优势和特色，经济学、管理学、法学、文学、理学等多学科协调发展的研究型大学。学校坐落于美丽的海滨城市辽宁省大连市，总占地面积65万平方米，是“辽宁最美校园”“辽宁省文明校园”。学校原名东北财经学院，始建于1952年，由解放初期党在东北地区创办的5所财经高校及东','2026-07-27 22:06:49','2026-08-08 00:13:07');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (144,'大连理工大学盘锦校区','辽宁','大连','https://hynu.site/logo/144.png','公办 本科 理工类 双一流 985 211。大连理工大学是中国共产党在新中国成立前夕，面向新中国工业体系建设亲手创办的第一所新型正规大学。大连理工大学是教育部直属全国重点大学，是国家“211工程”和“985工程”重点建设高校，也是世界一流大学A类建设高校。学校以培养精英人才、促进科技进步、传承优秀文化、引领社会风尚为宗旨，秉承“海纳百川、自强不息、厚德笃学、知行合一”的大工精神和“由','2026-07-27 22:06:49','2026-08-08 00:14:47');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (145,'哈尔滨工业大学（深圳）','广东','深圳','https://hynu.site/logo/145.png','公办 本科 理工类 双一流 985 211 工业和信息化部直属。哈尔滨工业大学始建于1920年，1951年被确定为全国学习国外高等教育办学模式的两所样板大学之一，1954年进入国家首批重点建设的6所高校行列，被誉为“工程师的摇篮”。学校于1996年进入国家“211工程”首批重点建设高校，1999年被确定为国家首批“985工程”重点建设的9所大学之一，2000年与同根同源的哈尔滨建筑大学合并组建新的哈工大，2017年入选“双一流”建设A类高校名','2026-07-27 22:06:49','2026-08-08 00:13:08');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (146,'哈尔滨工业大学（威海）','山东','威海','https://hynu.site/logo/146.png','公办 本科 理工类 双一流 985 211 工业和信息化部直属。2020年6月7日，习近平总书记致信祝贺哈尔滨工业大学建校100周年。贺信指出，哈尔滨工业大学历史悠久。新中国成立以来，在党的领导下，学校扎根东北、爱国奉献、艰苦创业，打造了一大批国之重器，培养了一大批杰出人才，为党和人民作出了重要贡献。希望哈尔滨工业大学在新的起点上，坚持社会主义办学方向，紧扣立德树人根本任务，在教书育人、科研攻关等工作中，','2026-07-27 22:06:49','2026-08-08 00:13:08');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (147,'北京师范大学（珠海校区）','广东','珠海','https://hynu.site/logo/147.png','公办 本科 综合类 双一流 985 211 教育部直属。北京师范大学珠海校区，是北师大建设“综合性、研究型、教师教育领先的中国特色世界一流大学”的重要组成部分，是按照学校“一体两翼”办学格局和“高标准、新机制、国际化”原则，打造的与北京校区一体规划、一体推进、一体呈现、同一水平的南方校区和增量改革示范区。利用毗邻港澳的独特优势和创新氛围，珠海校区旨在打造成为卓越教师尤其是国家急需学科师','2026-07-27 22:06:49','2026-08-08 00:13:09');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (148,'中山大学（深圳校区）','广东','广州','https://hynu.site/logo/148.png','公办 本科 综合类 双一流 985 211 教育部直属。中山大学是伟大的民族英雄、伟大的爱国主义者、中国民主革命的伟大先驱孙中山先生于1924年亲手创办，中国共产党早期领导人共同创建的大学，是中国传播马克思主义的重要发源地之一，具有优良革命传统、爱国奋斗精神和卓越品格追求。中山大学起初校名为国立广东大学。孙中山先生逝世后，学校于1926年定名为国立中山大学。今日的中山大学，由1952年院系调整后分设的','2026-07-27 22:06:49','2026-08-08 00:13:09');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (149,'北京理工大学（珠海校区）','北京','北京','https://hynu.site/logo/149.png','公办 本科 理工类 双一流 985 211 工业和信息化部直属。北京理工大学的前身是1940年诞生于延安的自然科学院，是中国共产党历史上第一个开展自然科学教学与研究的专门机构。毛泽东同志亲自题写校名，无产阶级革命家李富春，无产阶级革命家、教育家徐特立，无产阶级革命家、无线电专家、经济专家李强等先后担任学校主要领导。1949年，学校迁入北京；1952年，定名为北京工业学院，成为新中国第一所国防工业院校；1988年，更','2026-07-27 22:06:49','2026-08-08 00:13:10');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (150,'汕头大学','广东','汕头','https://hynu.site/logo/150.png','公办 本科 综合类 广东省直属。汕头大学是1981年经国务院批准成立的广东省省属综合性大学，是教育部、广东省、李嘉诚基金会三方共建的高等院校，全国首批高等教育综合改革试点高校，广东省高水平大学重点学科建设高校，广东省首家高等教育体制机制改革实验示范校，广东省深化新时代教育评价改革试点高校，广东省&quot;党建工作示范高校&quot;培育创建单位，也是全球唯一一所由私人基金会李嘉诚基','2026-07-27 22:06:49','2026-08-08 00:13:10');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (151,'深圳大学','广东','深圳','https://hynu.site/logo/151.png','公办 本科 综合类 广东省直属。特区大学、窗口大学、实验大学深圳大学1983年经教育部批准设立，肩负着为特区培养人才和为国家高等教育改革探路的光荣使命。中央、教育部和地方高度重视深圳大学建设，组织北大援建中文、外语类学科，清华援建电子、建筑类学科，人大援建经济、法律类学科，一大批知名学者云集深圳大学。建校伊始，学校在高校管理体制上锐意改革，在奖学金、学分制、勤工俭学等','2026-07-27 22:06:49','2026-08-08 00:13:11');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (152,'广东工业大学','广东','广州','https://hynu.site/logo/152.png','公办 本科 理工类 广东省直属。广东工业大学是一所以工为主、工理经管文法艺教结合、多科性协调发展的省属重点大学、广东省高水平大学重点建设高校，1958年开办本科教育，1995年由原广东工学院、广东机械学院和华南建设学院（东院）合并组建而成。2025泰晤士高等教育世界大学排名位列大陆高校第45—59位，2025软科世界大学学术排名位列全球第301—400名。学校本部坐落于中国南方名城广州，拥有大学城','2026-07-27 22:06:49','2026-08-08 00:13:12');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (153,'广东外语外贸大学','广东','广州','https://hynu.site/logo/153.png','公办 本科 语言类 广东省直属。广东外语外贸大学是广东省高水平大学重点建设高校。学校具有鲜明的国际化特色，是华南地区国际化人才培养，外国语言文学、全球治理、涉外法治研究及中华文化国际传播的重要基地。现有在校全日制本科生21144人，博士、硕士研究生6226人，各类成人本专科生、进修及培训生10000多人。2024-2025学年，共有来自99个国家的1656名外国留学生来我校学习。HISTORY历史沿革广东外语','2026-07-27 22:06:49','2026-08-08 00:13:12');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (154,'广州大学','广东','广州','https://hynu.site/logo/154.png','公办 本科 综合类 广东省直属。大学与城市共生共荣共成长。广州大学是以国家重要中心城市“广州”命名的综合性大学，于2000年合并组建，有着90多年的办学传统。学校紧紧抓住国家“双一流”建设、广东省和广州市高水平大学建设机遇，坚持“四个面向”，深化与广州和粤港澳大湾区“三个对接”，聚焦新工科、新文科、新师范建设，积极探索新医科和新农科发展，是广东省高水平大学建设计划重点建','2026-07-27 22:06:49','2026-08-08 00:13:13');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (155,'广州中医药大学','广东','广州','https://hynu.site/logo/155.png','公办 本科 医药类 双一流 广东省直属。广州中医药大学是首批国家“双一流”建设高校、广东高水平大学重点建设高校，也是广东省人民政府、教育部、国家中医药管理局共建中医药高校。学校肇始于1924年创办的广东中医药专门学校，1936年更名为广东中医药专科学校，1952年建设成为广东中医进修学校，1956年经国务院批准成立广州中医学院，是新中国首批四所高等中医药本科院校之一，1995年正式更名为广州中医药','2026-07-27 22:06:49','2026-08-08 00:13:13');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (156,'广东医科大学','广东','湛江','https://hynu.site/logo/156.png','公办 本科 医药类 广东省直属。广东医科大学的前身是中山医学院湛江分院，创建于1958年，1964年升格为五年制医学本科院校并更名为湛江医学院，1992年易名为广东医学院，2016年更名为广东医科大学。1960年被评为全国文教战线先进单位，1978年有2项科研成果获全国科学大会奖励，1986年获批硕士学位授权单位并列为广东省属重点建设大学，1991年获广东省办学水平评估一等奖，2005年在教育部本科教学工作水平','2026-07-27 22:06:49','2026-08-08 00:13:14');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (157,'广东药科大学','广东','广州','https://hynu.site/logo/157.png','公办 本科 医药类 广东省直属。广东药科大学是全国三所独立建制的药科大学之一，是华南地区最早开办药学系列专业的高等学府，1958年由原广东省卫生厅创办，开始于广东省卫生干部进修学院；1978年升格为普通本科高校，命名为广东医药学院；1994年易名广东药学院，2016年更名为广东药科大学。现有广州（大学城、宝岗、赤岗）、中山和云浮三大校区五个校园，占地5300亩。学校拥有本硕博完整的人才培养','2026-07-27 22:06:49','2026-08-08 00:13:14');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (158,'广东财经大学','广东','广州','https://hynu.site/logo/158.png','公办 本科 财经类 广东省直属。广东财经大学始建于1983年，原名广东财经学院，起始办学层次为本科教育，1985年更名为广东商学院，2003年获得硕士学位授予权，2013年更名为广东财经大学，2021年获批为博士学位授予单位。建校以来，学校秉承“厚德、励学、笃行、拓新”的校训，坚持“习礼乐文、精于术业”的办学理念和“法治、科学、民主、阳光”的治校方略，彰显“商法融合、实践创业、多元协同”的','2026-07-27 22:06:49','2026-08-08 00:13:15');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (159,'广东技术师范大学','广东','广州','https://hynu.site/logo/159.png','公办 本科 师范类 广东省直属。——服务产业，引领职教，构建“技术+师范”发展新格局学校坐落于广东省会城市、粤港澳大湾区中心城市——广州，是一所具有硕士学位授予权的省属高校。1977年开始培养本科生，2006年获批硕士学位授予单位，2021年获批广东省博士学位授予立项建设高校，是广东省“冲一流、补短板、强特色”特色提升计划建设高校，2025年获评“全国文明校园”光荣称号，学校发挥粤港澳','2026-07-27 22:06:49','2026-08-08 00:13:15');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (160,'广东海洋大学','广东','湛江','https://hynu.site/logo/160.png','公办 本科 综合类 广东省直属。广东海洋大学是广东省人民政府和自然资源部共建高校，是一所以海洋和水产学科为特色、多学科协调发展的综合性海洋大学，是广东省高水平大学重点学科建设高校。学校的前身是创建于1935年的广东省立高级水产职业学校，是广东现代海洋水产教育的发端，原暨南大学水产系、原华南工学院（现华南理工大学）湛江分院先后并入，1979年升格发展为农业部直属的湛江水产学院','2026-07-27 22:06:49','2026-08-08 00:13:16');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (161,'广东金融学院','广东','广州','https://hynu.site/logo/161.png','公办 本科 财经类 广东省直属。广东金融学院是一所省属公办普通本科院校，是华南地区唯一的金融类高校。学校由中国人民银行创办于1950年，是一所具有“央行基因”的院校。学校人才培养质量得到社会高度肯定和广泛认同，被誉为“华南金融人才摇篮”和“南粤金融黄埔军校”。进入21世纪，学校事业实现跨越式发展。2004年从“专科”升格为“本科”，2012年作为广东唯一获批服务国家特殊需求人才培养','2026-07-27 22:06:49','2026-08-08 00:13:17');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (162,'五邑大学','广东','江门','https://hynu.site/logo/162.png','公办 本科 综合类 广东省直属。五邑大学是由广东省人民政府于1985年设立的以工科为主的综合性公办高等学校，具有接收港澳台侨学生、国际学生资格和推荐优秀应届本科毕业生免试攻读研究生资格，现为博士学位授予立项建设单位和广东省高水平理工科大学建设高校。学校位于粤港澳大湾区重要节点城市、“中国侨都”——广东省江门市中心城区，校园环境优美，基础设施齐全，办学条件良好，占地面积1','2026-07-27 22:06:49','2026-08-08 00:13:17');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (163,'仲恺农业工程学院','广东','广州','https://hynu.site/logo/163.png','公办 本科 农林类 广东省直属。仲恺农业工程学院是一所以农、工学科为优势，农、工、理、经、管、文、艺、法等多学科协调发展的省属本科大学。学校坐落在历史文化名城广州，有白云、海珠两个校区，占地面积1600余亩。校园集帽峰之神秀，汇珠水之灵气，是读书治学的理想园地。学校前身是1925年由近代民主革命先驱何香凝先生等提议、为纪念伟大的爱国主义者廖仲恺先生爱护农工的意愿而决定创办的','2026-07-27 22:06:49','2026-08-08 00:13:18');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (164,'广东石油化工学院','广东','茂名','https://hynu.site/logo/164.png','公办 本科 理工类 广东省直属。广东石油化工学院是广东省人民政府与中国石油化工集团公司、中国石油天然气集团公司、中国海洋石油集团有限公司共建的公办普通本科高校，华南地区唯一一所石油化工特色高校，教育部“卓越工程师教育培养计划”试点高校，广东省高水平理工科大学建设高校，硕士学位授予单位，博士学位授予立项建设单位。学校地处中国南方最大的石化生产基地和水果生产基地、美','2026-07-27 22:06:49','2026-08-08 00:13:18');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (165,'岭南师范学院','广东','湛江','https://hynu.site/logo/165.png','公办 本科 师范类 广东省直属。岭南师范学院是一所具有百年师范教育积淀的广东省属公办高校，坐落在中国大陆最南端的美丽港城湛江市。学校历史源远流长，前身可追溯到1636年（明朝崇祯九年）在雷州府城创办的雷阳书院，1903年，书院改制为雷阳中学堂；1904年，开设简易师范科，标志着师范教育正式起步。此后，学校历经雷州中学校、广东省立第十中学等发展阶段，1935年成立广东省立雷州师范学校，1','2026-07-27 22:06:49','2026-08-08 00:13:19');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (166,'韩山师范学院','广东','潮州','https://hynu.site/logo/166.png','公办 本科 师范类 广东省直属。韩山师范学院（以下简称学校）是一所具有123年师范教育历史的广东省属公办高校，位于国家历史文化名城潮州市。学校前身可追溯到1090年（宋代元祐五年）为纪念唐宋八大家之首--韩愈而建的“韩山书院”。1903年（清光绪廿九年）改“韩山书院”为“惠潮嘉师范学堂”，成为中国第一批、广东第一所专门培养师资的学校。并先后于1912年更名为广东省立惠潮梅师范学校，1921','2026-07-27 22:06:49','2026-08-08 00:13:20');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (167,'嘉应学院','广东','梅州','https://hynu.site/logo/167.png','公办 本科 综合类 广东省直属。嘉应学院是一所有百年师范教育历史的广东省属全日制公办普通高校，坐落于国家历史文化名城、叶剑英元帅故乡、著名革命老区、全域属原中央苏区的广东省梅州市，是硕士学位授予单位、广东省创建国家教师教育创新实验区建设高校。学校面向23个省（自治区、直辖市）招生，现有普通全日制学生2.8万余人。学科覆盖文学、理学、工学、法学、医学等11个门类，拥有7个省级','2026-07-27 22:06:49','2026-08-08 00:13:20');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (168,'韶关学院','广东','韶关','https://hynu.site/logo/168.png','公办 本科 综合类 广东省直属。韶关学院是广东省属公办普通高等学校。举办师范教育始于1903年、医学教育始于1914年、高等教育始于1958年，先后由韶关师范专科学校、韶关大学、韶关教育学院、韶州师范学院、韶关医学院等5所学校合并组建而成。2000年升格本科，2004年获学士学位授予权，2024年获硕士学位授予单位。一、办学定位学校按照“1346”工作部署，以建设高水平应用创业型大学为发展目标定位，围','2026-07-27 22:06:49','2026-08-08 00:13:21');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (169,'惠州学院','广东','惠州','https://hynu.site/logo/169.png','公办 本科 综合类 广东省直属。惠州学院地处全国文明城市、国家历史文化名城、粤港澳大湾区重要节点城市——惠州，是省属全日制公办本科高校、硕士学位授予单位、全国新建本科院校联盟副理事长单位、普通本科转型试点高校和省创建国家教师教育创新实验区立项院校、省高校“三全育人”体制机制建设试点单位、省课程思政改革示范高校。学校前身为1946年创办的广东省立惠州师范学校，1978年升格为','2026-07-27 22:06:49','2026-08-08 00:13:21');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (170,'肇庆学院','广东','肇庆','https://hynu.site/logo/170.png','公办 本科 师范类 广东省直属。肇庆学院是由广东省人民政府主办、省教育厅主管的公办全日制本科高校。学校前身是1970年创办的肇庆地区师范学校，经历肇庆地区五·七师范学院、肇庆师范专科学校、西江大学等办学阶段。2000年，西江大学与肇庆教育学院合并组建本科层次肇庆学院。2021年，经国务院学位委员会批准，成为硕士学位授予单位。2024年，获批博士学位授予立项建设单位。五十多年来，学校始','2026-07-27 22:06:49','2026-08-08 00:13:22');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (171,'佛山科学技术学院','广东','佛山','https://hynu.site/logo/171.png','公办 专科（高职） 综合类。作为广东第二、中国第四个规上工业总产值超3万亿城市和中国唯一的制造业转型升级综合改革试点城市，佛山拥有发展现代职业教育的肥沃产业土壤和独特比较优势，这是佛山职业技术学院高质量发展的最大底气、最强信心。学校坐落于国家级工业园三水园区腹地，总占地面积883.51亩、建筑面积34.7万平方米，有教职工566人，全日制在校生12100余人，设有智能制造学院、电子信','2026-07-27 22:06:49','2026-08-08 00:14:48');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (172,'东莞理工学院','广东','东莞','https://hynu.site/logo/172.png','公办 本科 理工类 广东省直属。东莞理工学院坐落于经济活力强劲、先进制造业发达的粤港澳大湾区重要节点城市——广东东莞。学校于1990年经广东省人民政府批准筹建，1992年4月经原国家教育委员会批准成立，是东莞第一所公办本科院校，实行“省市共建、以市为主”的管理体制，是教育部首批卓越工程师教育培养计划试点高校、教育部首批高等教育综合改革试点高校、广东首批高水平理工科大学建设单','2026-07-27 22:06:49','2026-08-08 00:13:23');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (173,'广州美术学院','广东','广州','https://hynu.site/logo/173.png','公办 本科 艺术类 广东省直属。广州美术学院前身是中南美术专科学校，是根据国家建设布局，于1953年组建于湖北武汉的专门美术院校，时由中南文艺学院、华南人民文学艺术学院、广西省立艺术专科学校等院校相关系科和人员合并而成。首任校长为参加过延安文艺座谈会的著名革命美术家胡一川，首任副校长为著名油画家杨秋人、著名国画家关山月和阳太阳。1958年中南美术专科学校由武汉南迁广州，更名','2026-07-27 22:06:49','2026-08-08 00:13:23');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (174,'星海音乐学院','广东','广州','https://hynu.site/logo/174.png','公办 本科 艺术类 广东省直属。星海音乐学院由1957年创办的广州音乐学校发展而来，后数易校名、几经转制分合，育人初心矢志不渝。1958年9月升级为广州音乐专科学校，1966年1月与广东舞蹈学校合并为广东艺术专科学校，1970年10月与广州美术学院共同组建广东人民艺术学院，1978年3月复名为广州音乐专科学校，1981年6月经国务院批准设为广州音乐学院，1985年12月为纪念人民音乐家冼星海，更名为星海音乐学','2026-07-27 22:06:49','2026-08-08 00:13:24');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (175,'广州体育学院','广东','广州','https://hynu.site/logo/175.png','公办 本科 体育类 广东省直属。广州体育学院位于粤港澳大湾区核心引擎广州市中轴线上，创建于1956年，是新中国最早建设的体育高校之一，是华南地区唯一独立建制的具有本、硕、博人才培养体系的体育高等学府，是以体育学为主、多学科融合的现代大学。现有在校学生8000多人，其中研究生1300余人。1979年，学校开始研究生教育；1986年，学校成为广东省首批体育学硕士学位授予单位；2024年，学校获批博','2026-07-27 22:06:49','2026-08-08 00:13:24');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (176,'广东警官学院','广东','广州','https://hynu.site/logo/176.png','公办 本科 政法类 广东省直属。广东警官学院前身是广东省公安干部学校，创办于1949年11月，2004年5月经教育部批准设立“广东警官学院”。学校主管部门是广东省公安厅，教育教学业务主管部门是广东省教育厅。2008年获批学士学位授予权。2012年通过教育部本科教学工作合格评估。2018年获评广东省依法治校示范校。2019年完成教育部本科教学工作审核评估。2021年成为硕士学位授予立项建设单位。在76年的办','2026-07-27 22:06:49','2026-08-08 00:13:25');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (177,'广州航海学院','广东','广州','https://hynu.site/logo/177.png','公办 本科 综合类 广东省直属。凭海而立，因海而兴，向海图强。广州航海学院是华南地区唯一一所独立建制的海事本科院校，学校工程学（Engineering）学科是ESI全球排名前1%学科，航海类专业人才培养获中华人民共和国海事局许可、符合STCW国际公约标准，同时是全国第14所、华南地区第1所交通强国试点建设高校，是广东省首届“文明校园”单位、广东省绿色学校、广东省“冲补强”计划“强特色”建设高校','2026-07-27 22:06:49','2026-08-08 00:13:26');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (178,'北京师范大学-香港浸会大学联合国际学院','香港','九龙半岛','https://hynu.site/logo/178.png','内地与港澳台地区合作办学 本科 综合类。北师香港浸会大学（中文简称：北师港浸大；英文简称：BNBU）由北京师范大学与香港浸会大学于2005年携手创立，是中国第一家内地与香港高等教育界合作创办的大学、第一所创新的博雅型大学，也是广东省高水平大学重点学科建设高校。学校地处南海之滨、毗邻港澳，坐落于粤港澳大湾区的重要节点城市、近代中西文化交汇最早的地区之一——珠海。北师港浸大采用英文教学','2026-07-27 22:06:49','2026-08-08 00:14:50');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (179,'深圳北理莫斯科大学','广东','深圳','https://hynu.site/logo/179.png','中外合作办学 本科 综合类 广东省直属。深圳北理莫斯科大学是习近平主席与普京总统达成重要共识并推动创建，由深圳市人民政府、北京理工大学、莫斯科国立罗蒙诺索夫大学（简称莫斯科大学）三方合作设立的第一所中俄合作大学。2016年10月获教育部批准正式设立，2017年招收首批本科生和硕士研究生，2018年招收首批博士研究生，2020年获批博士后创新实践基地，2021年入选广东省高水平大学重点学科建设高校，2022','2026-07-27 22:06:49','2026-08-08 00:13:26');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (180,'广东以色列理工学院','广东','汕头','https://hynu.site/logo/180.png','中外合作办学 本科 理工类 广东省直属。广东以色列理工学院（英文缩写GTIIT）是由享誉全球的知名高等学府以色列理工学院（英文缩写Technion）与汕头大学（英文缩写STU）合作办学的一所具有独立法人资格的中外合作大学，是我国目前唯一一所理工科中外合作大学，也是以色列理工学院创建的中国校区，坐落于广东省汕头市。广东以色列理工学院于2016年12月5日由中国教育部批准正式设立，2017年第一年招生，是我国','2026-07-27 22:06:49','2026-08-08 00:13:27');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (181,'香港中文大学（深圳）','广东','深圳','https://hynu.site/logo/181.png','内地与港澳台地区合作办学 本科 综合类 广东省教育厅直属。香港中文大学（深圳）是一所经教育部批准，参照中外合作办学条例设立的大学。大学以创建一所立足中国、面向世界的一流研究型大学为己任，致力于培养具有国际视野、中华传统和社会担当的创新型高层次人才。大学的办学特色是国际化的氛围、中英并重的教学环境、书院制传统、通识教育、新型交叉学科设置和以学生为本的育人理念。目前，来自世界各地的10000多名优秀','2026-07-27 22:06:49','2026-08-08 00:13:27');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (182,'深圳技术大学','广东','深圳','https://hynu.site/logo/182.png','公办 本科 理工类 广东省直属。高端起点新学校深圳技术大学是广东省和深圳市高起点、高标准建设的公办本科大学，于2018年11月经教育部批准正式设立，2019年开始本、硕、博同时招生（硕士博士与深圳大学联合培养）。学校坚持“创新为本、需求驱动、开放融合、智能引领”办学理念，紧扣国家战略需要，紧密对接深圳、粤港澳大湾区产业需求，着力打造创新型工程师摇篮、企业家摇篮以及大湾区产业科','2026-07-27 22:06:49','2026-08-08 00:13:28');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (183,'广州南方学院','广东','广州','https://hynu.site/logo/183.png','民办 本科 综合类 广东省教育厅直属。实力强劲位居前列广州南方学院（原中山大学南方学院）是2006年经教育部批准设立的综合性应用型普通本科高等学校，以建设特色鲜明的一流应用型大学为使命，目前已获批成为广东省博士工作站设站单位、国家社会科学基金项目和国家自然科学基金项目依托单位。作为广东省高等教育多样化发展的旗帜，学校也是广东省高等教育体制综合改革试点院校、广东省首批普通本科','2026-07-27 22:06:49','2026-08-08 00:13:29');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (184,'广州华商学院','广东','广州','https://hynu.site/logo/184.png','民办 本科 综合类 广东省教育厅直属。广州华商学院（原广东财经大学华商学院），创办于2005年，2020年经教育部同意转设并更名为广州华商学院。学校是一所财经特色鲜明、多学科协调发展的全日制应用型本科高等学校，涵盖经、管、文、工、艺、教、理、医等多学科，现有广州校区、肇庆校区，分别坐落在风景秀丽的“荔枝之乡”广州增城和素有“中国玉器之乡”美誉的肇庆四会，校园占地面积87.86万㎡，在校','2026-07-27 22:06:49','2026-08-08 00:13:29');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (185,'广东白云学院','广东','广州','https://hynu.site/logo/185.png','民办 本科 综合类 广东省教育厅直属。广东白云学院是经教育部批准成立的全日制普通本科院校，由广东省教育厅主管。学校前身是谢可滔先生于1989年创办的广州白云应用技术学校，1999年经教育部批准成立白云职业技术学院，2001年更名为广东白云职业技术学院，2005年升格为本科高校并更名为广东白云学院，2009年获批学士学位授予权，2022年获批设立广东省博士工作站。面向全国17个省（自治区）招生，现有全日制','2026-07-27 22:06:49','2026-08-08 00:13:30');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (186,'广州软件学院','广东','广州','https://hynu.site/logo/186.png','民办 本科 理工类 广东省教育厅直属。广州软件学院成立于2002年，前身为广州大学华软软件学院，2020年12月，经教育部批准，广东省人民政府同意，转设更名为广州软件学院。学校董事长梁冠军先生是美国著名侨领、华人知名实业家、中华海外联谊会副会长、中国侨联顾问、中国和平统一促进会常务理事、美国美东华人社团联合总会主席。学校现有广州和江门两个校区。广州校区坐落在广州中新知识城北延区域的','2026-07-27 22:06:49','2026-08-08 00:13:30');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (187,'广州新华学院','广东','广州','https://hynu.site/logo/187.png','民办 本科 综合类 广东省教育厅直属。广州新华学院（原中山大学新华学院）成立于2005年5月，由中山大学与广东东宝集团有限公司合作创办。2021年2月，经教育部批准转设为独立设置的普通本科院校，更名为“广州新华学院”。2021年学校获批广东省硕士学位授予立项建设单位、广东省博士工作站单位，2022年获批国家自然科学基金依托单位，2025年一次性顺利通过教育部本科教学工作合格评估。学校位于粤港澳大湾','2026-07-27 22:06:49','2026-08-08 00:13:31');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (188,'广东培正学院','广东','广州','https://hynu.site/logo/188.png','民办 本科 财经类 广东省教育厅直属。广东培正学院创建于1993年，原名私立培正商学院。2005年，经教育部批准升格为本科院校并更名为广东培正学院。2009年，被广东省学士学位评定委员会批准为学士学位授予权单位；2012年，通过教育部本科教学工作合格评估；2018年，接受教育部本科教学工作审核评估；2024年，顺利接受教育部新一轮本科教育教学审核评估。学校由首任董事长梁尚立先生发起创建。梁尚立、林秀','2026-07-27 22:06:49','2026-08-08 00:13:31');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (189,'广州城市理工学院','广东','广州','https://hynu.site/logo/189.png','民办 本科 理工类 广东省教育厅直属。学校位于粤港澳大湾区中心城市——广州市，2004年由华南理工大学和广州云峰企业联合申请创办，2005年教育部批准设立华南理工大学广州汽车学院，2011年获批学士学位授予单位，同年更名为华南理工大学广州学院。2021年经教育部批准转设为独立设置的普通本科院校，同时更名为广州城市理工学院，是广东省首家选择非营利性办学的民办高校。2025年顺利通过本科教学工作合格','2026-07-27 22:06:49','2026-08-08 00:13:32');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (190,'广州理工学院','广东','广州','https://hynu.site/logo/190.png','民办 本科 综合类 广东省教育厅直属。广州理工学院是经教育部批准设立的全日制普通本科高校。学校创建于2000年，2006年成为独立学院、开办本科教育，2020年经教育部同意转设更名为广州理工学院。学校地处粤港澳大湾区和珠江三角洲核心地区，现有广州市白云区、广州市增城区、惠州市博罗县三个校区，区位优势明显。学校以习近平新时代中国特色社会主义思想为指导，贯彻党的教育方针，坚持社会主义办学','2026-07-27 22:06:49','2026-08-08 00:13:33');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (191,'广东科技学院','广东','东莞','https://hynu.site/logo/191.png','民办 本科 综合类 广东省教育厅直属。广东科技学院创建于2003年，是教育部批准设立的一所以工学为主，管理学、经济学、文学、艺术学等多学科协调发展的全日制普通本科院校，坐落于“粤港澳大湾区重要节点城市”──东莞，拥有南城和松山湖两个校区，占地面积2000余亩。学校于2011年经教育部批准升格为本科院校，2015年取得学士学位授予权，2018年通过教育部本科教学工作合格评估，2021年成功入选广东省硕','2026-07-27 22:06:49','2026-08-08 00:13:33');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (192,'广东理工学院','广东','肇庆','https://hynu.site/logo/192.png','民办 本科 理工类 广东省教育厅直属。广东理工学院是经国家教育部批准设立的全日制普通本科高等院校，扎根粤港澳大湾区腹地——肇庆市，秉持应用型办学定位，致力于培养德智体美劳全面发展、具有创新精神、实践能力的高素质应用型人才，积极服务区域经济社会发展。学校肇始于1995年创建的肇庆科技培训学校，2001年更名为肇庆科技学校，2004年升格为肇庆科技职业技术学院；2014年，依据《教育部关于同意','2026-07-27 22:06:49','2026-08-08 00:13:34');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (193,'广州工商学院','广东','广州','https://hynu.site/logo/193.png','民办 本科 财经类 广东省教育厅直属。广州工商学院是教育部批准设立的全日制普通本科院校，创办于1995年，前身是广州工商职业技术学院，2014年升格为本科。学校秉承“以质立校、以生为本、突出特色、崇尚创新”的办学理念，弘扬“正德厚生、励志修能”的校训精神，发扬“博学善教、修己达人”的教风和“勤学敏思、求实创新”的学风，坚持“地方性、应用型、国际化”的办学定位，2024年通过教育部本科','2026-07-27 22:06:49','2026-08-08 00:13:35');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (194,'广东东软学院','广东','佛山','https://hynu.site/logo/194.png','民办 本科 理工类 广东省教育厅直属。广东东软学院是经教育部批准设立，由东软出资举办的一所民办普通高等院校，成立于2002年。前身是南海东软信息技术职业学院（高职专科）。学校是国家教育部认定的“国家级技能型紧缺人才（信息技术类）培养基地”（2005年），以及“广东省首批示范性软件学院”（2004年）。其中，“18MALL创业园”“华南东软IT创业园”先后获得“国家级众创空间”和“国家级科技企业孵','2026-07-27 22:06:49','2026-08-08 00:13:35');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (195,'湛江科技学院','广东','湛江','https://hynu.site/logo/195.png','民办 本科 综合类 广东省教育厅直属。❑学校简介湛江科技学院坐落在中国大陆最南端的美丽港城湛江市，是一所全日制普通本科院校。学校于1999年由广东海洋大学与湛江寸金教育集团合作创办，2006年经教育部批准为独立学院，2021年经教育部批准转设为独立设置的民办普通本科高校。经过20余年的建设和发展，学校已成为粤西地区规模最大、具有重要区域性影响、办学特色鲜明的民办本科高校，先后获得“广东民','2026-07-27 22:06:49','2026-08-08 00:13:36');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (196,'广东工商职业技术大学','广东','肇庆','https://hynu.site/logo/196.png','民办 本科 综合类 广东省教育厅直属。广东工商职业技术大学是2018年教育部批准设置的全国首批职业本科院校，2019年经教育部批准更名为广东工商职业技术大学，前身为1996年创建的肇庆工商职业技术学校，2022年经广东省学位委员会批准为学士学位授予单位，2023年经广东省教育厅批准具备招收留学生资格。学校位于粤港澳大湾区腹地、国家历史文化名城——肇庆市，现有星湖和大旺两个校区，星湖校区毗邻肇庆七','2026-07-27 22:06:49','2026-08-08 00:13:36');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (197,'广州科技职业技术大学','广东','广州','https://hynu.site/logo/197.png','民办 本科 综合类 广东省教育厅直属。1999年，广东景大经济发展有限公司投资创办了广东南大专修学院，2004年经广东省人民政府批准成为广州科技职业技术学院，2018年升格为本科层次职业学校，2019年经教育部批准，更名为“广州科技职业技术大学”。学校形成一校两区的发展布局。广州校区位于白云区钟落潭高校园区内，滨海校区位于茂名市电白区高地智慧城。学校占地面积共2074亩，建筑面积74.01万平方米。现','2026-07-27 22:06:49','2026-08-08 00:13:37');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (198,'电子科技大学中山学院','广东','中山','https://hynu.site/logo/198.png','民办 本科 综合类 广东省教育厅直属。电子科技大学中山学院为全日制普通本科独立学院，合作双方为中山市人民政府和国家重点建设的“世界一流大学”A类高校电子科技大学。学校建校至今已有40年的办学历史。前身为1986年成立的中山大学孙文学院；1995年更名为中山学院，实行省市共管，以市为主的管理体制；2002年至今，合作双方中山市人民政府和电子科技大学共同举办电子科技大学中山学院；2016年以来，学','2026-07-27 22:06:49','2026-08-08 00:13:38');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (199,'华南农业大学珠江学院','广东','广州','https://hynu.site/logo/199.png','民办 本科 综合类 广东省教育厅直属。华南农业大学珠江学院是2006年4月经教育部批准设立，实施全日制本科层次教育的独立学院。学院实施“一校两区”办学模式，校区分别位于有“温泉之都”美誉的广州从化和有“翡翠之乡”之称的肇庆四会，用地面积1757.47亩，校园环境优美，区位优势独特，现有全日制在校生19000余人。学院牢记为党育人、为国育才使命，秉持“国际视野、创新赋能、特色发展、服务社会、追','2026-07-27 22:06:49','2026-08-08 00:13:38');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (200,'广州华立学院','广东','广州','https://hynu.site/logo/200.png','民办 本科 理工类 广东省教育厅直属。广州华立学院（原广东工业大学华立学院）建于1999年，2004年经教育部批准，成为广东省第一批独立学院，全面实施本科教育。2021年经教育部同意，转设为广州华立学院。学校现有广州增城和江门银湖湾两个校区，校园占地近2000亩；设有16个学院，51个本科专业，在校全日制普通本科生24500余人，是一所工学、经济学、管理学、文学、艺术学、教育学和理学等多学科协调发展，','2026-07-27 22:06:49','2026-08-08 00:13:39');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (201,'广东外语外贸大学南国商学院','广东','广州','https://hynu.site/logo/201.png','民办 本科 综合类 广东省教育厅直属。学校始建于1996年，经历了广州市南国女子学校、广州市南国工商学校和广州南国工商专修学院的发展过程，2006年经教育部批准正式成立广东外语外贸大学南国商学院，为一所本科层次的独立学院。学校坐落于国家中心城市广州，毗邻白云国际机场、高铁广州白云站。学校占地面积900余亩。校园环境幽雅、空气清新、湖光山色、绿树成荫。学校办学设备设施完善，教学管理严格','2026-07-27 22:06:49','2026-08-08 00:13:39');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (202,'北京理工大学珠海学院','广东','珠海','https://hynu.site/logo/202.png','公办 本科 理工类 双一流 985 211。北京理工大学的前身是1940年诞生于延安的自然科学院，是中国共产党历史上第一个开展自然科学教学与研究的专门机构。毛泽东同志亲自题写校名，无产阶级革命家李富春，无产阶级革命家、教育家徐特立，无产阶级革命家、无线电专家、经济专家李强等先后担任学校主要领导。1949年，学校迁入北京；1952年，定名为北京工业学院，成为新中国第一所国防工业院校；1988年，更','2026-07-27 22:06:49','2026-08-08 00:15:38');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (203,'珠海科技学院','广东','珠海','https://hynu.site/logo/203.png','民办 本科 综合类 广东省教育厅直属。稳居软科中国民办高校排名前三珠海科技学院（原吉林大学珠海学院）成立于2004年5月18日，2011年获批学士学位授予单位，先后与吉林大学、华南师范大学、吉林化工大学、广东工业大学、哈尔滨体育学院、广州中医药大学、长春工业大学、吉林财经大学、重庆师范大学开展联合培养硕士/博士研究生合作，2021年获批广东省硕士学位授予立项建设单位。现设18个二级学院、71个本','2026-07-27 22:06:49','2026-08-08 00:13:40');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (204,'广州应用科技学院','广东','广州','https://hynu.site/logo/204.png','民办 本科 综合类 广东省教育厅直属。广州应用科技学院是经教育部批准设立的全日制普通本科高校。前身是2000年创办的广州大学松田学院，2020年12月经教育部批准转设并更现名。学校地处粤港澳大湾区，设有广州校区与肇庆校区，实行“一校两区”协同发展，面向全国招生，全日制在校本科生32655人。现有在校生32655人占地面积（亩）1120现有教师1575名本科专业50个图书馆总面积（平方米）：47000广州应用科技学院','2026-07-27 22:06:49','2026-08-08 00:13:40');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (205,'东莞城市学院','广东','东莞','https://hynu.site/logo/205.png','民办 本科 理工类 广东省教育厅直属。学校概况东莞城市学院是经教育部批准设立的普通本科高等学校。始建于2004年，原为东莞理工学院城市学院，2021年转设并更名为东莞城市学院。20余年来，学校秉承“厚德务实，知行合一”的校训精神，坚持“深耕东莞、面向湾区、辐射全国”的服务定位，为国家经济建设和社会发展培养了一大批德才兼备的高素质应用型专业人才。党建工作学校荣获2个国家级党建工作样板支','2026-07-27 22:06:49','2026-08-08 00:13:41');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (206,'广州商学院','广东','广州','https://hynu.site/logo/206.png','民办 本科 综合类 广东省教育厅直属。广州商学院位于粤港澳大湾区东北部，坐落在“中新广州知识城”核心区域。学校前身是华南师范大学增城学院，1999年招收第一批学生；2002年成为广东省第一所新机制二级学院；2004年成为全国第一批、广东省第一所独立学院；2014年成为广东省第一所由独立学院转设的普通本科高校；2020年通过教育部本科教学工作合格评估；2021年成为广东省第一批民办高校硕士学位立项建设','2026-07-27 22:06:49','2026-08-08 00:13:42');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (207,'广东第二师范学院','广东','广州','https://hynu.site/logo/207.png','公办 本科 师范类 广东省直属。广东第二师范学院是广东省属普通本科院校，其前身为1955年创办的广东教育行政学院，1960年更名为广东教育学院，同年，广东工农师范学院并入，1970年停办，迁往肇庆开办肇庆地区师范学校，1978年复办，1982年被确定为省属成人师范本科院校，并于同年开始举办成人师范本科教育，1985年开始举办普通专科教育，1990至2008年举办普通本科教育。2010年经教育部批准，改制为普通','2026-07-27 22:06:49','2026-08-08 00:13:42');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (208,'香港科技大学（广州）','广东','广州','https://hynu.site/logo/208.png','内地与港澳台地区合作办学 本科 理工类 广东省教育厅直属。香港科技大学（广州）是一所经国家教育部批准设立的内地与香港合作大学港科大(广州)是《粤港澳大湾区发展规划纲要》及《广州南沙深化面向世界的粤港澳全面合作总体方案》颁布实施以来成立的首家具有独立法人资格的内地与香港合作办学机构，于2022年6月正式成立。香港科技大学（广州）锐意创新，以发展融合学科为特色，探索创新人才培养模式，以建设成为内地与香','2026-07-27 22:06:49','2026-08-08 00:13:43');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (209,'香港大学（深圳）','香港','香港岛','https://hynu.site/logo/209.png','公办 本科 综合类 香港特别行政区。历史悠久——香港大学(港大)于1911年建校，是香港历史最悠久的大学。教研成绩显赫，校内有十名老师先后获选为中国科学院院士。港大长久以来肩负着香港、中国、亚洲及世界各地学术交流枢纽的重任，努力不懈为世界的学术交流和人才培养作出贡献。国际大学——香港大学为国际知名的高等学府，多次获本港及国际媒体高度评价为亚洲及太平洋地区(包括澳大利亚)最佳大学','2026-07-27 22:06:49','2026-08-08 00:13:43');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (210,'肇庆医学高等专科学校','广东','肇庆','https://hynu.site/logo/210.png','公办 本科 医药类。肇庆医学院是一所全日制公办普通本科高校。学校办学历史可追溯至1958年创建的中山医学院肇庆分院，2004年升格为肇庆医学高等专科学校；2024年5月，教育部正式批准以肇庆医学高等专科学校为基础设立肇庆医学院。学校传承“大医精诚、知行合一”的校训，立足粤港澳大湾区及粤东西北地区，辐射全国，面向基层培养“下得去、留得住、用得好”的高素质医药卫生人才，办','2026-07-27 22:06:49','2026-08-08 00:14:53');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (211,'深圳职业技术大学','广东','深圳','https://hynu.site/logo/211.png','公办 本科 综合类 广东省直属。深圳职业技术大学是一所公办本科层次职业院校，其前身是1993年创建的深圳职业技术学院。2023年6月，教育部批准以深圳职业技术学院为基础整合资源设立深圳职业技术大学，学校成为教育部印发实施《本科层次职业学校设置标准（试行）》以来，全国第一所以优质“双高”学校为基础设置的本科层次职业学校。建校以来，学校以立德树人为根本任务，坚定职教本色，坚持深','2026-07-27 22:06:49','2026-08-08 00:13:44');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (212,'广东轻工职业技术学院','广东','广州','https://hynu.site/logo/212.png','公办 本科 理工类。广东轻工职业技术大学是国家“双高计划”学校、国家优质高职院校、国家示范性高职院校。学校前身是创建于1933年的“广东省立第一职业学校”，至今已有93年职业教育历史。学校坚持以习近平新时代中国特色社会主义思想为指导，贯彻党的教育方针，围绕立德树人根本任务，面向粤港澳大湾区，服务国家战略和区域现代产业发展，落实省委“1310”具体部署，秉承“德能兼','2026-07-27 22:06:49','2026-08-08 00:14:55');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (213,'广州番禺职业技术学院','广东','广州','https://hynu.site/logo/213.png','公办 本科 综合类。广州职业技术大学（原名番禺理工学院、番禺职业技术学院、广州番禺职业技术学院）1993年筹建，1997年9月教育部（原国家教委）正式批准备案，是广州市属第一所公办全日制普通高等职业院校。筹建伊始，番禺籍的全国政协原副主席霍英东，全国政协副主席、澳门特别行政区首任行政长官何厚铧，陈瑞球、何添、何善衡等港澳同胞和社会各界有识之士慷慨捐资，为学校发展','2026-07-27 22:06:49','2026-08-08 00:14:56');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (214,'顺德职业技术学院','广东','佛山','https://hynu.site/logo/214.png','公办 本科 综合类。粤港澳大湾区腹地的佛山是中国第4个“工业3万亿”城市，佛山顺德是“世界制造名城”“世界美食之都”“中国家电之乡”“中国涂料之乡”“中国家具之都”，连续14年位列全国综合实力百强区榜首。坐落于佛山顺德的顺德职业技术大学，是一所全日制公办本科层次职业院校，其前身是1999年创建的顺德职业技术学院。筹建伊始，顺德籍的李兆基、郑裕彤等港澳同胞，美的、','2026-07-27 22:06:49','2026-08-08 00:14:58');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (215,'广东科学技术职业学院','广东','广州','https://hynu.site/logo/215.png','公办 专科（高职） 综合类 广东省直属。广东科学技术职业学院（广东省科技干部学院）是全日制省属公办普通高等职业学校，正厅级建制，是中国特色高水平高职学校和专业建设计划建设单位、国家示范性（骨干）高职院校、国家优质专科高等职业院校。学校前身为1985年创建的广东省科技干部进修学院，隶属广东省科学技术委员会；1989年改名为广东省科技干部学院；1996年成为广东省首批举办普通高职教育的院校','2026-07-27 22:06:49','2026-08-08 00:13:45');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (216,'广东交通职业技术学院','广东','广州','https://hynu.site/logo/216.png','公办 专科（高职） 理工类 广东省直属。广东交通职业技术学院（以下简称学院）的前身是1959年成立的广东交通学校和1960年成立的广东省航运学校。1999年经教育部批准，将两校合并组建广东交通职业技术学院。2008年7月，学院由广东省交通运输厅整建制划转广东省教育厅管理。2022年10月，广东省华侨职业技术学校、广东省科技职业技术学校通过省属职业院校集团办学并入学院。学院坚持“立足交通，服务粤港澳区域','2026-07-27 22:06:49','2026-08-08 00:13:45');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (217,'广东水利电力职业技术学院','广东','广州','https://hynu.site/logo/217.png','公办 专科（高职） 理工类 广东省直属。广东水利电力职业技术学院始建于1952年，是一所行业特色鲜明的省属公办全日制高等职业院校，学校前身为广州土木水利工程学校，1999年升格为高等职业院校，2018年12月学校由广东省水利厅划转广东省教育厅管理。2019年入选中国特色高水平职业学校和高水平专业群（“双高计划”）建设单位。学校坚持以习近平新时代中国特色社会主义思想为指导，贯彻党的教育方针，始终','2026-07-27 22:06:49','2026-08-08 00:13:46');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (218,'广州铁路职业技术学院','广东','广州','https://hynu.site/logo/218.png','公办 专科（高职） 理工类 广东省直属。广州铁路职业技术学院（简称学校）前身为成立于1974年5月22日的原铁道部广州铁路司机学校。2000年6月，经广东省人民政府批准，由广州铁路机械学校、广州铁路运输职工大学与广州铁路成人中等专业学校合并升格为全日制公办高等职业院校。2004年9月，学校由广州铁路（集团）公司（现为中国铁路广州局集团有限公司，简称广铁集团）移交广州市人民政府举办。学校现为国家','2026-07-27 22:06:49','2026-08-08 00:13:47');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (219,'广州民航职业技术学院','广东','广州','https://hynu.site/logo/219.png','公办 专科（高职） 理工类 交通运输部（中国民用航空局）直属。广州民航职业技术学院直属中国民用航空局，是民航内最早一所独立设置实施高等职业教育的全日制公办普通高校。作为民航高层次技术技能人才培养的国家队、主力军、主基地，学校经过40多年的建设与发展，已成为我国民航专业门类最全、培养规模最大、能力最强、水平最高，享誉国内、在东南亚民航有着较高影响力的职业院校，为我国民航强国建设、粤港澳大湾区和广东','2026-07-27 22:06:49','2026-08-08 00:13:47');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (220,'广东机电职业技术学院','广东','广州','https://hynu.site/logo/220.png','公办 专科（高职） 理工类 广东省直属。广东机电职业技术学院是一所隶属于广东省教育厅的公办全日制工科类普通高等职业院校。学院办学历史悠久，前身为创建于1956年的广东省农业机械化学校，历经“广东省农业机械化技工学校”“广东省农业机械技术学校”“广东省农业机电学校”“广东省机电学校”等发展阶段，2001年，升格为高等职业院校。2021年、2026年，学院先后与广东省经济贸易职业技术学校、广东省','2026-07-27 22:06:49','2026-08-08 00:13:48');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (221,'广东工贸职业技术学院','广东','广州','https://hynu.site/logo/221.png','公办 专科（高职） 理工类 广东省教育厅直属。广东工贸职业技术学院是广东省人民政府直属的一所全日制普通高等职业院校。前身为1957年成立的广东省冶金工业学校，历经广州有色金属工业学校（1984年）等阶段，2002年升格为高职院校。2021年起与广东省商业职业技术学校实施集团办学。学校位于广州市，地理位置优越，现设天河、白云、荔湾三个校区，总占地面积1085亩，全日制在校生21000余人。学校致力于培养基础知识','2026-07-27 22:06:49','2026-08-08 00:13:48');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (222,'广东食品药品职业学院','广东','广州','https://hynu.site/logo/222.png','公办 专科（高职） 医药类 广东省直属。广东食品药品职业学院创建于1965年，是一所经广东省人民政府批准、教育部备案的公办全日制普通高等职业院校。学校前身是广东省中药材学校，校址在广州市塞坝口；1974年迁址至浆栏路并更名为广东省商业技校第一分校；1979年改为广东省医药技工学校；1983年成立广东省医药职工中专学校，与广东省医药技工学校一起办学；1984年迁址至广州市天河区龙洞，1986年成立广东省','2026-07-27 22:06:49','2026-08-08 00:13:49');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (223,'广东农工商职业技术学院','广东','广州','https://hynu.site/logo/223.png','公办 专科（高职） 综合类 广东省直属。广东农工商职业技术学院是一所普通高等公办全日制专科院校。学校创建于1952年，前身为叶剑英元帅在兼任华南垦殖局局长期间创办的华南垦殖局机务学校，1977年经广东省革命委员会批准成立广东省农垦干部学校，1984年经广东省人民政府批准成立广东农垦管理干部学院，开始举办大专学历教育，1989年经原农业部批准挂牌“农业部华南农垦干部培训中心”，1993年更名为广东农','2026-07-27 22:06:49','2026-08-08 00:13:50');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (224,'广东职业技术学院','广东','佛山','https://hynu.site/logo/224.png','公办 专科（高职） 综合类 广东省直属。广东职业技术学院是由广东省人民政府主办的全日制普通高等职业院校，行政主管部门是广东省教育厅。其前身为广东省纺织工业学校，筹建于1984年,1985年正式招生，1993年被评为省级重点中专学校，2000年被评为国家级重点中专学校，2001年升格为广东纺织职业技术学院。2012年，经广东省人民政府批准，学校更名为广东职业技术学院。2021年7月，与广东省工业贸易职业技术学校','2026-07-27 22:06:49','2026-08-08 00:13:50');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (225,'广东建设职业技术学院','广东','广州','https://hynu.site/logo/225.png','公办 专科（高职） 理工类 广东省直属。广东建设职业技术学院——“现代鲁班摇篮”【发展沿革底蕴深厚】广东建设职业技术学院是一所以建筑为特色，集理、工、商、贸为一体的综合性省属公办高职院校，是建筑业高素质技术技能人才培养的主要基地，被誉为“现代鲁班摇篮”。学校已培养培训30多万名高素质技术技能型人才，为广东省建设行业与经济社会发展做出了积极贡献。学校前身是1979年成立的广东省建','2026-07-27 22:06:49','2026-08-08 00:13:51');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (226,'广东工程职业技术学院','广东','广州','https://hynu.site/logo/226.png','公办 专科（高职） 理工类 广东省直属。广东工程职业技术学院是广东省域高水平高职院校建设单位、广东省示范性高等职业院校。学校创建于1958年，前身是广东省成人科技大学。学校坚守为党育人、为国育才初心使命，秉承“工于建构成于创造”的校训精神，锚定“根植智造、立足广东、服务湾区、走向世界”的办学定位，主动对接湾区现代产业体系和新质生产力发展需求，践行开放创新、产教融合、数智赋能的','2026-07-27 22:06:49','2026-08-08 00:13:52');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (227,'广东科贸职业学院','广东','清远','https://hynu.site/logo/227.png','公办 专科（高职） 综合类 广东省直属。广东科贸职业学院是一所隶属于广东省教育厅的公办高等职业院校。学校成立于1985年，其前身是先后隶属于省农委、省农办、省农业厅的广东省农业管理干部学院。2006年学院正式转制为高等职业学院并更名为“广东科贸职业学院”，同年进驻白云校区；2009年正式归属省教育厅管理；2019年进驻省职教城（清远）校区。现有省职教城（清远）和广州白云、天河三个校区，在校学','2026-07-27 22:06:49','2026-08-08 00:13:52');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (228,'广东司法警官职业学院','广东','广州','https://hynu.site/logo/228.png','公办 专科（高职） 政法类 广东省直属。广东司法警官职业学院（以下简称学院）2002年4月经广东省人民政府批准，在广东省司法警察学校（始建于1982年4月）、广东司法学校（始建于1982年11月）基础上合并组建而成，是全日制公办普通高等学校。学院设龙洞和石井两校区，主校区设在龙洞。学院为副厅级建制，归省司法厅管理，在教学及专业建设等方面受省教育厅指导。学院是广东司法行政系统人才培养基地、司法','2026-07-27 22:06:49','2026-08-08 00:13:53');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (229,'广东省外语艺术职业学院','广东','广州','https://hynu.site/logo/229.png','公办 专科（高职） 综合类 广东省直属。广东省外语艺术职业学院（以下简称“广外艺”）是广东省人民政府2001年12月批准设立的省属副厅级建制普通高等职业院校，办学最早可追溯至1956年5月，前身是广东外国语师范学校和广东艺术师范学校。2021年，经广东省人民政府批准，广东省民政职业技术学校、广东省对外贸易职业技术学校和广东省贸易职业技术学校通过集团办学并入学校。一、办学条件优良学校现有教职','2026-07-27 22:06:49','2026-08-08 00:13:54');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (230,'广东文艺职业学院','广东','广州','https://hynu.site/logo/230.png','公办 专科（高职） 艺术类 广东省直属。文以载道，艺以弘德。广东文艺职业学院是一所具有光荣历史传统和深厚文化积淀的大学，始建于1950年，前身是由毛泽东主席题写校名、叶剑英元帅亲自创办的“华南人民文学艺术学院”。1985年，成立“华南文艺业余大学”，校长由省委宣传部副部长、省文联党组书记杜埃兼任，刘田夫、欧阳山任名誉校长，文艺大家关山月、黎雄才、郭绍纲、杨之光担任顾问。1995年更名为','2026-07-27 22:06:49','2026-08-08 00:13:54');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (231,'广东体育职业技术学院','广东','广州','https://hynu.site/logo/231.png','公办 专科（高职） 体育类 广东省直属。广东体育职业技术学院（以下简称“学校”）前身是1956年8月创办的广东省体育运动学校，2003年5月升格为全日制普通高等职业院校，是省属唯一体育类高职院校。2020年6月，学校成建制由广东省体育局划转广东省教育厅管理。建校以来，学校为粤港澳大湾区乃至全国培养了冼东妹、傅海峰、江嘉良、孙彩云、董兆致等一大批为国家作出突出贡献的体育明星以及约10万余名竞技体','2026-07-27 22:06:49','2026-08-08 00:13:55');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (232,'广东行政职业学院','广东','广州','https://hynu.site/logo/232.png','公办 专科（高职） 综合类 广东省直属。广东行政职业学院为省属公办A类高职院校，现有花都、白云两个校区。校园总面积500余亩，在校学生近1.3万人，校舍建筑面积17万平方米。校园环境清新优美，教学条件完善，教学管理规范，生活设施齐全，是青年学子求学成才的理想选择。学校现设有公共管理学院、社会工作学院（政法学院）、智慧政务学院（电子信息学院）、外语外贸学院（国际交流学院）、财政金融学','2026-07-27 22:06:49','2026-08-08 00:13:55');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (233,'广东女子职业技术学院','广东','广州','https://hynu.site/logo/233.png','公办 专科（高职） 综合类 广东省直属。广东女子职业技术学院创办于1981年，前身是广东省妇女干部学校，2018年12月，成建制由省妇联划转至省教育厅管理，是华南地区唯一一所公办女子高职院校。2020年4月，学校被确定为省示范性高等职业院校；2022年被立项为“省域高水平高等职业院校建设计划培育单位”；在2022年、2023年和2024年“创新强校工程”考核中排名全省A类高职院校第9、11位和14位。2015年以来，学校被认','2026-07-27 22:06:49','2026-08-08 00:13:56');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (234,'广东青年职业学院','广东','佛山','https://hynu.site/logo/234.png','公办 专科（高职） 综合类。广东职业技术学院是由广东省人民政府主办的全日制普通高等职业院校，行政主管部门是广东省教育厅。其前身为广东省纺织工业学校，筹建于1984年,1985年正式招生，1993年被评为省级重点中专学校，2000年被评为国家级重点中专学校，2001年升格为广东纺织职业技术学院。2012年，经广东省人民政府批准，学校更名为广东职业技术学院。2021年7月，与广东省工业贸易职业技术学校','2026-07-27 22:06:49','2026-08-08 00:15:31');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (235,'广东松山职业技术学院','广东','韶关','https://hynu.site/logo/235.png','公办 专科（高职） 理工类 广东省直属。广东松山职业技术学院是由广东省人民政府举办、广东省教育厅直属管理的全日制普通高等职业院校，有50年办学历史，是全省转设高等职业院校最早的院校之一。学校前身为广东韶关钢铁集团职工大学，始办于1976年3月，办学初期校名为韶关钢铁厂“七二一”工人大学；2000年6月，经广东省人民政府批准改制为普通高等职业学校；2014年6月，由宝钢集团韶关钢铁有限公司移交广','2026-07-27 22:06:49','2026-08-08 00:13:57');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (236,'广东环境保护工程职业学院','广东','佛山','https://hynu.site/logo/236.png','公办 专科（高职） 理工类 广东省直属。广东环境保护工程职业学院（以下简称学校）是2010年2月经广东省人民政府批准设立的全日制公办高等职业院校，以培养绿色低碳、生态环境、节能安全等相关产业高素质技术技能人才为主要特色，隶属广东省教育厅。学校是在广东省环境保护职业技术学校（创建于1978年）基础上成立的。2013年，学校与广东省环境保护职业技术学校分别独立办学。2021年，学校与广东省环境保护','2026-07-27 22:06:49','2026-08-08 00:13:57');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (237,'广东舞蹈戏剧职业学院','广东','广州','https://hynu.site/logo/237.png','公办 专科（高职） 艺术类。广东艺术职业学院是历史悠久、声誉卓著的省属公立艺术类高职院校，源自1958年成立的广东粤剧学校和1959年创建的广东舞蹈学校，历经数次名称变迁，曾用名广东艺术专科学校、广东人民艺术学院等。2012年2月，经广东省人民政府批准，广东舞蹈学校和广东粤剧学校合并建立广东舞蹈戏剧职业学院，隶属原广东省文化厅（广东省文化和旅游厅），2019年2月，学校成建制划转广','2026-07-27 22:06:49','2026-08-08 00:15:32');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (238,'广东生态工程职业学院','广东','广州','https://hynu.site/logo/238.png','公办 专科（高职） 农林类 广东省直属。广东生态工程职业学院（以下简称学校）是2014年3月经广东省人民政府批准设立的全日制公办普通高等职业学院。学校前身隶属于广东省林业厅，2018年，学校成建制移交广东省教育厅管理。2021年，学校与广东省海洋工程职业技术学校（创办于1935年）实施集团办学。学校现有天河校区、海珠校区及阳江校外实训基地，合计2200亩。在校学生近2.1万名。近年来，学校综合实力稳步','2026-07-27 22:06:49','2026-08-08 00:13:58');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (239,'广东梅州职业技术学院','广东','梅州','https://hynu.site/logo/239.png','公办 专科（高职） 综合类 广东省直属。广东梅州职业技术学院是经广东省人民政府批准、国家教育部核准设立的公办全日制普通高等学校。高考录取批次：专科批次，学制3年，2021年秋季开始正式招生。学院位于广东省梅州市梅江区学院路，坐落在风景秀美的周溪河畔。校园占地面积600亩，包括校本部东区、西区、北区，广梅产业园校区，总建筑面积30万平方米，规划在校生1.2万人。学院设置农业工程学院、信息工','2026-07-27 22:06:49','2026-08-08 00:13:58');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (240,'广东潮州卫生健康职业学院','广东','潮州','https://hynu.site/logo/240.png','公办 专科（高职） 医药类 广东省直属。广东潮州卫生健康职业学院是潮州市政府举办的公办全日制普通高等专科学校，学制三年，2021年秋季学期正式启用、招生办学，填补了潮州市没有公办高职院校和粤东地区没有公办卫生健康类高职院校两大空白。2024年底，潮州市委、市政府实施市属高职资源整合，将韩山师范学院潮州师范分院整体并入我校，丰富了办学资源，增强了办学实力。学校坐落于潮州市凤泉湖高新区','2026-07-27 22:06:49','2026-08-08 00:13:59');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (241,'广东云浮中医药职业学院','广东','云浮','https://hynu.site/logo/241.png','公办 专科（高职） 医药类 广东省直属。广东云浮中医药职业学院创办于2021年，是一所由广东省人民政府批准设立、经教育部备案，由云浮市人民政府主办的具有高等学历教育招生资格的一所全日制公办普通高等学校。学校坚持党的领导，全面贯彻新时代党的教育方针，落实立德树人根本任务，坚持“以人为本、德业双修、全面发展”的教育理念，坚定“合理规划，抓住重点，打造特色”的办学思路，培养适应中医','2026-07-27 22:06:49','2026-08-08 00:13:59');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (242,'广东汕头幼儿师范高等专科学校','广东','汕头','https://hynu.site/logo/242.png','公办 专科（高职） 师范类 广东省直属。2021年5月10日，教育部正式下发《教育部办公厅关于公布实施专科教育高等学校和成人高等学校备案名单的函》，公布了2021年度省级人民政府审批新设、更名、合并调整、撤销的专科层次高等学校和成人高等学校备案名单，其中，汕头市新设广东汕头幼儿师范高等专科学校获得批复，计划于2021年秋季正式开学（学校代码：14757）。优化教育布局解决粤东地区幼教资源配备需求近','2026-07-27 22:06:49','2026-08-08 00:14:00');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (243,'广东江门中医药职业学院','广东','江门','https://hynu.site/logo/243.png','公办 专科（高职） 医药类 广东省直属。广东江门中医药职业学院肇始于1958年创办的新会县中级卫生学校，1984年更名为江门卫生学校，1992年更名为广东省江门中医药学校，2017年3月经广东省人民政府批准、教育部备案，设立为公办全日制高等职业院校，2022年9月，学校成功入选广东省省域高水平高职院校培育单位。学校是全国第一所、粤港澳大湾区唯一一所中医药类高职院校，坐落于中国第一侨乡——中国侨都广东','2026-07-27 22:06:49','2026-08-08 00:14:01');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (244,'广东茂名幼儿师范专科学校','广东','茂名','https://hynu.site/logo/244.png','公办 专科（高职） 师范类 广东省直属。广东茂名幼儿师范专科学校位于祖国南海之滨、“好心之城”、中国魅力城市——茂名。茂名是国家“一带一路”倡议中“一带”的重要城市，地处粤港澳大湾区、北部湾经济区、海南自由贸易试验区三大经济圈的交汇处，地理位置优越，交通方便，风景优美、气候宜人。学校是广东省人民政府批准、教育部备案的全日制公办普通高等专科院校，是广东省第一所幼教师范高等','2026-07-27 22:06:49','2026-08-08 00:14:01');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (245,'广东湛江幼儿师范专科学校','广东','湛江','https://hynu.site/logo/245.png','公办 专科（高职） 师范类。湛江幼儿师范专科学校是广东省人民政府2016年2月批准设立的全日制公办高等职业院校，是广东省第一批幼儿师范高等专科学校。学校坚持立德树人的社会主义办学方针，秉承“笃学、笃行、致真、致远”的校训精神。立足湛江，实施“双百行动”赋能粤西学前教育高质量发展；面向广东，实施“百千万工程”助力地方经济社会高质量发展；服务全国，深化改革，努力建成特色','2026-07-27 22:06:49','2026-08-08 00:15:02');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (246,'广州城建职业学院','广东','广州','https://hynu.site/logo/246.png','民办 专科（高职） 理工类 广东省教育厅直属。广州城建职业学院是经广东省人民政府批准、教育部备案，于2007年在原广州大学城建学院基础上独立设置的一所全日制理工类民办高等职业院校。学校办学历史可追溯至1960年，先后历经“广州市业余建筑工程学院”“广州市建筑工程局职工大学”“广州市建筑总公司职工大学”“广州大学城建技术学院”“广州大学城建学院”等历史沿革。2022年，学校入选广东省高水平高等','2026-07-27 22:06:49','2026-08-08 00:14:02');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (247,'广州涉外经济职业技术学院','广东','广州','https://hynu.site/logo/247.png','民办 专科（高职） 财经类 广东省教育厅直属。广州涉外经济职业技术学院是2004年经广东省人民政府批准、教育部备案的省属全日制普通高职院校。学校由中国涉外教育集团旗下广东维城经济发展有限公司于1999年投资创办，至今已有25年历史。学校依托涉外教育集团雄厚的办学实力和集团化办学优势，秉承“依法治校，质量立校，人才强校，特色兴校”的办学理念，取得了良好的办学成效和社会声誉。近年来，先后荣获了','2026-07-27 22:06:49','2026-08-08 00:14:02');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (248,'广州南洋理工职业学院','广东','广州','https://hynu.site/logo/248.png','民办 专科（高职） 理工类 广东省教育厅直属。广州南洋理工职业学院，是经广东省人民政府批准、教育部备案的省属全日制普通高等学校，简称“南洋理工”。学校坐落在有“广州后花园”之称的广州市从化区，其前身是上海交通大学与西安交通大学的广州校友为传承和发扬南洋公学“教育报国”精神于1984年创办的广州南洋自学辅导大学。学校以“创百年学府，育产业精英”为愿景与使命，以“建设大湾区优质高职院校','2026-07-27 22:06:49','2026-08-08 00:14:03');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (249,'广州华立科技职业学院','广东','广州','https://hynu.site/logo/249.png','民办 专科（高职） 综合类 广东省教育厅直属。广州华立科技职业学院是经广东省人民政府批准、国家教育部备案的全日制普通高职院校。学校始建于1999年6月，至今已有20余年办学历史。现有广州和云浮两个校区。广州校区地处穗莞深港黄金走廊和广深科技创新走廊的重要节点，位于具有全国综合实力百强区、全国绿色发展百强区、全国科技创新百强区美誉的广州市增城区，与著名的北汽集团华南基地隔路相望；云浮校区','2026-07-27 22:06:49','2026-08-08 00:14:03');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (250,'广东岭南职业技术学院','广东','广州','https://hynu.site/logo/250.png','民办 专科（高职） 综合类 广东省教育厅直属。广东岭南职业技术学院始办于1993年的“广州岭南文化技术学校”，2001年5月经广东省人民政府批准成立，是一所以大健康类专业为主体，以电子信息类和智能制造类、财经商贸类和文化艺术类专业为支撑的民办高等职业技术院校。学院现有广州和清远两大校区，截至2025年9月，校园总面积1241亩，校舍建筑面积70万余平方米，教学、科研仪器设备总值2.13亿元，纸质图书逾183万册','2026-07-27 22:06:49','2026-08-08 00:14:04');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (251,'广东文理职业学院','广东','湛江','https://hynu.site/logo/251.png','民办 专科（高职） 综合类 广东省教育厅直属。广东文理职业学院（以下简称“学校”）是经广东省人民政府批准设立、国家教育部备案的全日制普通高等职业院校。学校创办于2006年，原名为湛江现代科技职业学院，2012年更名为广东文理职业学院。学校占地面积1830亩，建筑面积70.9万平方米。学校目前正积极推进“广东奥克体育中心”建设，其中包括“劳丽诗跳水馆”等现代化设施。学校坚持“生态文理、人文文理、特色','2026-07-27 22:06:49','2026-08-08 00:14:05');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (252,'广州华南商贸职业学院','广东','广州','https://hynu.site/logo/252.png','民办 专科（高职） 财经类 广东省教育厅直属。广州华南商贸职业学院是2005年经广东省人民政府批准、教育部备案的财经商贸类全日制普通高等专科职业院校，与广东科技学院（应用型本科）、广州南洋理工职业学院（理工类高职专科）同属广东南博教育集团。学校坐落于广州第二大学城——白云区钟落潭镇健康城高校园区，其前身是于1998年创办的广州工商管理专修学院。学校规划占地面积900亩，拥有教学仪器设备总值超','2026-07-27 22:06:49','2026-08-08 00:14:05');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (253,'广州华商职业学院','广东','广州','https://hynu.site/logo/253.png','民办 专科（高职） 综合类 广东省教育厅直属。广州华商职业学院是由改革开放第一批企业家、香港中华职教社创办人廖榕就博士投资兴建，2009年经广东省人民政府批准设立、国家教育部备案、广东省教育厅主管的一所民办高等学校，是全国青年联合会常委单位、粤港澳大湾区青年职业发展促进会创办单位、香港中华职教社创办单位、教育部“一站式”学生综合社区试点单位、广东省博士工作站建设单位。学校坚持“创百','2026-07-27 22:06:49','2026-08-08 00:14:06');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (254,'广东创新科技职业学院','广东','东莞','https://hynu.site/logo/254.png','民办 专科（高职） 理工类 广东省教育厅直属。学校概况广东创新科技职业学院是2011年2月经广东省人民政府批准设立的全日制民办高等职业院校。学校位于粤港澳大湾区核心城市东莞，地处广深科技创新走廊黄金节点，毗邻香港，区位优势显著，产业资源密集。学校秉承“厚德自强，创新不息”校训，聚焦高素质技术技能人才培养，深度融入粤港澳大湾区高质量发展大局，持续为区域现代产业体系输送生力军。办学条件学','2026-07-27 22:06:49','2026-08-08 00:14:06');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (255,'广东酒店管理职业技术学院','广东','东莞','https://hynu.site/logo/255.png','民办 专科（高职） 综合类 广东省教育厅直属。广东酒店管理职业技术学院成立于2016年4月，是经广东省人民政府批准、国家教育部备案、广东省教育厅主管的一所全日制普通高等职业院校。学校坐落在粤港澳大湾腹地—东莞市，毗邻广州深圳，位处香港、深圳、广州半小时生活圈，地理环境优越，区位优势明显。经过10年的改革、建设与发展，学校现有8个二级学院和一个中职部、42个招生专业，全日制在校生16700多人。一','2026-07-27 22:06:49','2026-08-08 00:14:07');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (256,'广东信息工程职业学院','广东','肇庆','https://hynu.site/logo/256.png','民办 专科（高职） 理工类 广东省教育厅直属。广东信息工程职业学院（GuandongInformationEngineeringInstitute）始创于2012年，经广东省人民政府批准、教育部备案、广东省教育厅主管的全日制民办普通高等职业院校。学校坐落于粤港澳大湾区一小时经济圈的广东肇庆（大旺）国家高新技术开发区内，距广州50多公里，广佛肇城际、珠三角环线高速（G94）、二广高速（G55）、广佛肇高速（S8）均可到达，学校距珠三角环线高速大旺北','2026-07-27 22:06:49','2026-08-08 00:14:08');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (257,'惠州城市职业学院','广东','惠州','https://hynu.site/logo/257.png','公办 专科（高职） 综合类 广东省直属。惠州城市职业学院于2014年3月经广东省人民政府批准成立，是广东省教育厅主管的一所公办全日制普通高等院校，学院前身是惠阳地区供销学校、惠阳专区粮食学校和惠阳地区商业学校。1964年惠阳专区粮食学校在东莞县石龙镇成立，期间历经惠阳地区粮食学校、广东省惠州市粮食学校、广东省惠州外贸学校，2007年被认定为国家级重点中等职业学校。惠阳地区供销学校创办于1964','2026-07-27 22:06:49','2026-08-08 00:14:08');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (258,'惠州卫生职业技术学院','广东','惠州','https://hynu.site/logo/258.png','公办 专科（高职） 医药类 广东省直属。惠州卫生职业技术学院成立于2012年，是广东省第一所卫生类高职院校。学校前身可追溯至1958年成立的“广东省惠阳卫生学校”。建校60余年来，累计为社会输送了十万名医药卫生类人才，被誉为东江流域培养白衣天使的摇篮。2018届护理专业毕业生刘家怡援鄂抗疫的先进事迹家喻户晓，她那一句“穿上防护服我就不是孩子了”感动了全中国，也获得了习近平总书记的点赞。还有','2026-07-27 22:06:49','2026-08-08 00:14:09');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (259,'汕尾职业技术学院','广东','汕尾','https://hynu.site/logo/259.png','公办 专科（高职） 综合类 广东省直属。汕尾职业技术学院成立于2001年5月21日，学校是在原汕尾师范学校、汕尾中等专业学校（前身溯源海陆丰公学）基础上组建的一所公办全日制普通高等职业院校。学校办学渊源可追溯至1947年——在中共华南（香港）分局的指示下，东江纵队在港人员创办香港海陆丰公学，使其成为我党在香港的重要教育阵地，更为学校积淀了深厚的红色基因。作为广东省一类革命老区唯一的公办','2026-07-27 22:06:49','2026-08-08 00:14:09');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (260,'揭阳职业技术学院','广东','揭阳','https://hynu.site/logo/260.png','公办 专科（高职） 综合类 广东省直属。揭阳职业技术学院创建于1999年，地处全国著名侨乡、广东省历史文化名城、广东沿海经济带东翼主战场——揭阳，是经广东省人民政府批准设立、教育部备案，由揭阳市人民政府举办的公办全日制普通高等职业院校。办学以来，学校秉承“诚真、笃教、博学、致用”校训，以“立德强技，人才强校，服务地方”为办学理念，以“立足揭阳、辐射粤东、面向广东”为办学定位，','2026-07-27 22:06:49','2026-08-08 00:14:10');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (261,'阳江职业技术学院','广东','阳江','https://hynu.site/logo/261.png','公办 专科（高职） 综合类 广东省直属。阳江职业技术学院成立于2001年5月，经教育部备案、广东省人民政府批准设立，由阳江市人民政府举办，是一所综合性普通高等学校。学校前身可追溯至1916年创办的阳江师范学校，是关山月、许章衡、谢天赐、陈章绩等艺术名家的母校。学校现有党政管理机构9个、教学机构12个、教辅机构3个；全日制在校生1万多人，教职员工579人，其中高级职称150人、省级职业教育“双师型”','2026-07-27 22:06:49','2026-08-08 00:14:11');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (262,'清远职业技术学院','广东','清远','https://hynu.site/logo/262.png','公办 专科（高职） 综合类 广东省直属。清远职业技术学院成立于2002年。学院位于清远市清城区，距广州市中心仅60多公里，毗邻白云国际机场，许广高速、广乐高速、京广铁路纵贯南北，京广高铁在市区设清远站，广清城轨（首期）清城往返花都、白云国际机场，交通便捷。学院设有继续教育学院、护理学院、外语与经贸学院、机电与汽车工程学院、旅游家政与艺术学院、信息技术与创意设计学院、食品药品学院','2026-07-27 22:06:49','2026-08-08 00:14:11');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (263,'河源职业技术学院','广东','河源','https://hynu.site/logo/263.png','公办 专科（高职） 综合类 广东省直属。河源职业技术学院是一所由河源市人民政府主办的全日制地方高职院校。学校自升格成立高职之初，便以“厚德强技，服务地方”为办学宗旨，2018年成为广东省示范性高职院校（粤东西北地区首批），2022年成为广东省域高水平高职院校建设单位（粤东西北唯一）。学校是国家职业院校数字校园建设实验校、教育部“一站式”学生社区试点、教育部现代学徒制试点校、国家节约','2026-07-27 22:06:49','2026-08-08 00:14:12');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (264,'中山职业技术学院','广东','中山','https://hynu.site/logo/264.png','公办 专科（高职） 综合类 广东省直属。中山职业技术学院地处广东省中山市。中山原名香山，因纪念孙中山先生而得名，位于粤港澳大湾区的几何中心。2004年中山市委、市政府批准筹建，2006年经广东省人民政府批准设立。学校占地840亩，现有全日制学生9915人，教职员工599人。荣获“国家优质专科高等职业院校”(2019)、“全国职业院校教学管理50强”“全国高职院校教学资源50强”(2019)、“全国高职院校服务贡献50','2026-07-27 22:06:49','2026-08-08 00:14:13');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (265,'江门职业技术学院','广东','江门','https://hynu.site/logo/265.png','公办 专科（高职） 综合类 广东省直属。江门职业技术学院位于粤港澳大湾区重要节点城市——中国侨都广东江门，是2004年7月挂牌成立的全日制公办普通高等职业院校。学校以“技术立校、文化育人、开放办学、服务侨乡”为办学理念，占地1100多亩，现有教职工800多人，全日制在校生近14000人。学校校园毗邻西江，风景优美，教学实训、文体运动、一站式社区设施齐全，图书馆藏书丰富。办学历史学校由原江门教育','2026-07-27 22:06:49','2026-08-08 00:14:13');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (266,'佛山职业技术学院','广东','佛山','https://hynu.site/logo/266.png','公办 专科（高职） 综合类 广东省直属。作为广东第二、中国第四个规上工业总产值超3万亿城市和中国唯一的制造业转型升级综合改革试点城市，佛山拥有发展现代职业教育的肥沃产业土壤和独特比较优势，这是佛山职业技术学院高质量发展的最大底气、最强信心。学校坐落于国家级工业园三水园区腹地，总占地面积883.51亩、建筑面积34.7万平方米，有教职工566人，全日制在校生12100余人，设有智能制造学院、电子信','2026-07-27 22:06:49','2026-08-08 00:14:14');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (267,'珠海城市职业技术学院','广东','珠海','https://hynu.site/logo/267.png','公办 专科（高职） 综合类 广东省直属。珠海城市职业技术学院是由珠海市人民政府举办的全日制普通高等学校，2004年4月经广东省人民政府批准，由原珠海教育学院、珠海广播电视大学、原珠海市工业学校、原珠海市财贸学校合并组建而成，经过近20年的发展，办学实力显著提升。一、深耕内涵建设，提升办学实力学校2004年成立，2011年通过人才培养工作水平评估。2013年开始，在珠海市委、市政府的大力支持下，学','2026-07-27 22:06:49','2026-08-08 00:14:14');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (268,'汕头职业技术学院','广东','汕头','https://hynu.site/logo/268.png','公办 专科（高职） 综合类 广东省直属。汕头职业技术学院坐落于美丽的海滨城市汕头市。汕头是全国著名侨乡、国家经济特区、广东省域副中心城市，地处韩江、榕江、练江出海口，素有“华南要冲、岭东门户”之称，是广东省距离台湾最近的城市。2020年10月13日习近平总书记亲临汕头经济特区考察。2021年2月广东省委、省政府出台政策支持汕头建设新时代中国特色社会主义现代化活力经济特区。汕头职业技术学院','2026-07-27 22:06:49','2026-08-08 00:14:15');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (269,'罗定职业技术学院','广东','云浮','https://hynu.site/logo/269.png','公办 专科（高职） 综合类 广东省直属。罗定职业技术学院是2001年5月在罗定师范学校基础上成立的一所公办全日制普通高等职业院校，前身是创建于1928年的罗定县立女子乡村师范学校。学校设立有国家职业技能鉴定所、广东省博士工作站，建立了云浮市云计算大数据人才培养基地、云浮市电子信息产业技术服务中心、云浮市自动化设备工程技术研究中心、云浮市南江文化研究中心，成立学校科学技术协会、社科联','2026-07-27 22:06:49','2026-08-08 00:14:16');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (270,'茂名职业技术学院','广东','茂名','https://hynu.site/logo/270.png','公办 专科（高职） 理工类 广东省教育厅直属。茂名职业技术学院是一所以工科为主的公办高职院校,广东省省域高水平高职院校建设高校（培育单位），获评为茂名市文明校园。学校地处中国南方最大的石化生产基地和水果生产基地、建筑之乡、美丽的海滨城市——广东省茂名市，占地面积66.6万平方米（约1000亩），分北校区、南校区、人民南3个校区。学校1986年创校，秉承“修德强技求实创新”校训，坚持“价值观+知识+','2026-07-27 22:06:49','2026-08-08 00:14:16');
INSERT INTO `university` (`id`, `name`, `province`, `city`, `logo_url`, `description`, `created_at`, `updated_at`) VALUES (271,'广州体育职业技术学院','广东','广州','https://hynu.site/logo/271.png','公办 专科（高职） 体育类 广东省直属。院歌：飞翔是我的梦想,广州体育职业技术学院,1分钟广州体育职业技术学院(挂广州市体工队牌子，以下简称学院)的前身为创办于1973年的广州市中心业余体校，1985年改制为广州市体育运动学校，1996年更名为广州市伟伦体育运动学校，同年，广州市体工队并入学校。2004年3月，经广东省人民政府批准、教育部备案，升格为广州市人民政府举办的全日制高等体育职业院校，是唯一','2026-07-27 22:06:49','2026-08-08 00:14:17');
